static const smolhelpentry SmolHelpData[SMOLHELP_NENTRY]={
	{"statement","Statements about the configuration file",0,"#",
		"  # text",
		"    Single-line comment. A # symbol indicates that the rest of the line is a\n"
		"    comment."},
	{"statement","Statements about the configuration file",0,"/*",
		"  /* text */",
		"    Multi-line comment. All lines between /* and the following */ are ignored.\n"
		"    These must be the first \"words\" on a line. Additional text on these lines\n"
		"    is ignored as well. In future versions, the syntax of these may be changed\n"
		"    so as to be identical to C-style block comments."},
	{"statement","Statements about the configuration file",0,"read_file",
		"  read_file filename",
		"    Read some other configuration file, returning to the present one when that\n"
		"    one has been read."},
	{"statement","Statements about the configuration file",0,"end_file",
		"  end_file",
		"    End of configuration file. This line is optional (but good programming\n"
		"    practice), as Smoldyn can also just read until the file ends."},
	{"statement","Statements about the configuration file",0,"units",
		"  units units",
		"    This specifies the units that should be assumed for numerical quantities\n"
		"    that are read from the configuration file. If this is the first units\n"
		"    statement, then the working units (for Smoldyn's computations and output)\n"
		"    are set to these units. These units continue to be assumed until another\n"
		"    units statement is encountered, whether within the same file or at the top\n"
		"    of a sub-file. At the end of a sub-file (or upon an end_units statement),\n"
		"    any units that are defined in that sub-file are no longer assumed and\n"
		"    Smoldyn reverts to the units of the higher-level file."},
	{"statement","Statements about the configuration file",0,"working_units",
		"  working_units units",
		"    Define the working units, meaning the units that Smoldyn uses for internal\n"
		"    computations and output. If this statement is not entered, which is\n"
		"    typical, then the working units are set to the first units that are listed\n"
		"    with the units statement."},
	{"statement","Statements about the configuration file",0,"end_units",
		"  end_units",
		"    Stop using the current default units and return to the prior ones. If units\n"
		"    are defined for a sub-file, then they are automatically ended when the file\n"
		"    ends; it's a good idea to add this statement at the end of the sub-file,\n"
		"    but it's not necessary."},
	{"statement","Statements about the configuration file",0,"quit_at_end",
		"  quit_at_end value",
		"    Use a value of \"yes\" to tell the simulator to quit the program at the end\n"
		"    of the simulation, during simulations that use graphics. This has no effect\n"
		"    if simulations do not use graphics. Use \"no\" to turn this off, which is the\n"
		"    default behavior. This same behavior can also be achieved by creating and\n"
		"    setting the shell environment variable SMOLDYN_NO_PROMPT to any value."},
	{"statement","Statements about the configuration file",0,"define",
		"  define key substitution",
		"    Definition of macro replacement text. Throughout the remainder of this\n"
		"    configuration file, but not files that are called by it, all incidents of\n"
		"    the string key are replaced with the string substitution before further\n"
		"    parsing is performed. It is permissible to not include any substitution\n"
		"    text."},
	{"statement","Statements about the configuration file",0,"define_global",
		"  define_global key substitution",
		"    Definition of macro replacement text, which is identical to define, except\n"
		"    that this definition applies throughout both this file and all files that\n"
		"    are called by it. Global definitions can also be entered on the command\n"
		"    line using the --define option."},
	{"statement","Statements about the configuration file",0,"undefine",
		"  undefine key",
		"    Removes a macro substitution definition that was made previously, whether\n"
		"    global or local. Global undefines apply to this file and all files that are\n"
		"    called by it, but not to a file that called this one. Entering key as \"all\"\n"
		"    undefines all definitions."},
	{"statement","Statements about the configuration file",0,"ifdefine",
		"  ifdefine key",
		"    The following lines of the configuration file are read only if key is a\n"
		"    term that was defined with define or define_global (or was defined\n"
		"    automatically, which includes FILEROOT). Reading, or not reading, continues\n"
		"    to any else statement. The end of the condition is given with the endif\n"
		"    statement."},
	{"statement","Statements about the configuration file",0,"ifundefine",
		"  ifundefine key",
		"    This is identical to ifdefine, except that reading continues only if key\n"
		"    has not been defined."},
	{"statement","Statements about the configuration file",0,"else",
		"  else",
		"    This is the else condition which is supposed to follow an ifdefine or\n"
		"    ifundefine statement."},
	{"statement","Statements about the configuration file",0,"endif",
		"  endif",
		"    This ends a condition that is started by an ifdefine or ifundefine\n"
		"    statement."},
	{"statement","Statements about the configuration file",0,"display_define",
		"  display_define",
		"    Causes all current definitions to be displayed to the standard output. This\n"
		"    is only useful for debugging define issues in configuration files."},
	{"statement","Statements about variables",0,"variable",
		"  variable var = value",
		"    Sets the value of variable var to value, which needs to evaluate to a\n"
		"    numerical value. Note that spaces and the equals sign are required.\n"
		"    Variables cannot have units."},
	{"statement","Statements about space and time",0,"dim",
		"  dim dim",
		"    Dimensionality of the system, between 1 and 3."},
	{"statement","Statements about space and time",0,"boundaries",
		"  boundaries dim pos_1 pos_2\n"
		"  boundaries dim pos_1 pos_2 type",
		"    Creates lower and upper boundaries to define the simulation volume on\n"
		"    dimension dim. The dim value should be \"x\", \"y\", or \"z\" (however, 0, 1, and\n"
		"    2 work as well). These boundaries are located at pos_1 and pos_2. Using the\n"
		"    first format, which is advised for systems that include surfaces,\n"
		"    boundaries are created that are transparent to molecules, meaning that they\n"
		"    do not contain or otherwise interact with molecules. Surfaces need to be\n"
		"    defined to keep molecules in the system. The second format is preferable\n"
		"    for systems that do not include any surfaces. In this case, the boundary\n"
		"    type can be \"r\" for reflective, \"t\" for transparent, \"a\" for absorbing, or\n"
		"    \"p\" for periodic. For most purposes, this statement replaces the low_wall\n"
		"    and high_wall statements."},
	{"statement","Statements about space and time",0,"low_wall",
		"  low_wall dim pos type",
		"    This statement has been largely superseded by boundaries. This creates a\n"
		"    lower boundary for the simulation volume. This wall is perpendicular to the\n"
		"    dimension dim (\"x\", \"y\", or \"z\") such that all locations between pos and\n"
		"    the position of the corresponding upper boundary are considered to be\n"
		"    within the simulation volume. The type of wall is given in type, which\n"
		"    should be one of four single letter codes: \"r\" means a reflecting wall, \"p\"\n"
		"    means a periodic wall (also called wrap-around or toroidal), \"a\" means an\n"
		"    absorbing wall, and \"t\" means a transparent wall. Transparent walls imply\n"
		"    an unbounded system and may lead to slow simulations. If any surfaces are\n"
		"    defined for the simulation, then walls still must be entered to define the\n"
		"    system volume, but these walls are essentially non-functional (the sole\n"
		"    exception is that reactions can occur across periodic walls). Additional\n"
		"    surfaces need to be defined to serve as the system boundaries."},
	{"statement","Statements about space and time",0,"high_wall",
		"  high_wall dim pos type",
		"    This statement has been largely superseded by boundaries. This is identical\n"
		"    to the definition for low_wall, although this creates the upper boundary\n"
		"    for the simulation volume."},
	{"statement","Statements about space and time",0,"time_start",
		"  time_start time",
		"    Starting point for simulated time."},
	{"statement","Statements about space and time",0,"time_stop",
		"  time_stop time",
		"    Stopping time of simulation, using simulated time. The simulation continues\n"
		"    past the time_stop value by less than one time step."},
	{"statement","Statements about space and time",0,"time_step",
		"  time_step time",
		"    Time step for the simulation. Longer values lead to a faster runtime, while\n"
		"    shorter values lead to higher accuracy. Also, longer values lead to\n"
		"    bimolecular reactions that behave more as though they are activation\n"
		"    limited, rather than diffusion limited."},
	{"statement","Statements about space and time",0,"time_now",
		"  time_now time",
		"    Another starting time of simulation. Default value is equal to time_start.\n"
		"    If this time is before time_start, the simulation starts at time_start;\n"
		"    otherwise, it starts at time_now."},
	{"statement","Statements about molecules",0,"species",
		"  species name_1 name_2 ... name_n",
		"    Names of one of more molecular species present in the system. Standard\n"
		"    naming conventions are followed, in that the name should start with a\n"
		"    letter and spaces are not permitted."},
	{"statement","Statements about molecules",0,"species_group",
		"  species_group group species_1 species_2 ...",
		"    Defines a group of species called group and adds species_1, species_2, and\n"
		"    potentially other species to this group. Empty groups are allowed. Any\n"
		"    number of species can be added. If the group already exists, the named\n"
		"    species will be added to the existing group. These groups can be used in\n"
		"    most statements and commands that have species inputs, where they enable\n"
		"    operations on multiple species at once. However, they cannot be used in\n"
		"    reactions."},
	{"statement","Statements about molecules",0,"difc difc_rule",
		"  difc species value\n"
		"  difc species(state) value\n"
		"  difc_rule species(state) value",
		"    Isotropic diffusion coefficient of molecule type species. Default value is\n"
		"    0. The state, which is optional, refers to the surface-bound state of the\n"
		"    molecule: solution, front, back, up, or down; if omitted, only the solution\n"
		"    state is set with this statement. name may be \"all\" and/or state may be\n"
		"    \"all\" to set diffusion coefficients for multiple species at once. If the\n"
		"    rule form is used (generally with wildcard characters), then the statement\n"
		"    is not applied immediately but is stored for use during rule expansion;\n"
		"    during rule expansion, it is applied to all species that match the given\n"
		"    species pattern."},
	{"statement","Statements about molecules",0,"difm difm_rule",
		"  difm species float_0 float_1 ... float_(dim*dim-1)\n"
		"  difm species(state) float_0 float_1 ... float_(dim*dim-1)\n"
		"  difm_rule species(state) float_0 float_1 ... float_(dim*dim-1)",
		"    Square root of diffusion matrix of species and maybe state state (the dot\n"
		"    product of this matrix and itself is the anisotropic diffusion matrix). The\n"
		"    matrix has dim^2 terms (dim is the system dimensionality), listed row by\n"
		"    row of the matrix; the matrix is supposed to be symmetric. If this line is\n"
		"    not entered, isotropic diffusion is assumed, which leads to a faster\n"
		"    runtime. While a matrix is used for diffusion if one is given, the value\n"
		"    stored with difc is used for reaction rate calculations. If difc is not\n"
		"    entered, the trace of the square of this matrix, divided by the system\n"
		"    dimensionality, is used as a proxy for the isotropic diffusion coefficient\n"
		"    to allow reaction rates to be estimated. This line is most useful for\n"
		"    restricting diffusion to a plane or a line, in which case the square root\n"
		"    of the diffusion coefficient is given for each diagonal element of the\n"
		"    matrix where there is diffusion and 0s are place on diagonal elements for\n"
		"    axes where diffusion is not possible, as well as on off-diagonal elements.\n"
		"    species and or state may be \"all\" to set diffusion matrices for multiple\n"
		"    species at once. If the rule form is used (generally with wildcard\n"
		"    characters), then the statement is not applied immediately but is stored\n"
		"    for use during rule expansion; during rule expansion, it is applied to all\n"
		"    species that match the given species pattern.\n"
		"\n"
		"    Because this is the square root of the diffusion matrix, each term should\n"
		"    have units of L*T^(-1/2), where L is length and T is time. Smoldyn's unit\n"
		"    conversion can't handle this, so units cannot be entered with this\n"
		"    statement."},
	{"statement","Statements about molecules",0,"drift drift_rule",
		"  drift species float_0 float_1 ... float_(dim-1)\n"
		"  drift species(state) float_0 float_1 ... float_(dim-1)\n"
		"  drift_rule species(state) float_0 float_1 ... float_(dim-1)",
		"    Drift velocity vector for molecules of type species and maybe state state.\n"
		"    The vector has dim terms (dim is the system dimensionality). If this line\n"
		"    is not entered, there is no net drift. species and/or state may be \"all\" to\n"
		"    set drift vectors for multiple species at once. If the rule form is used\n"
		"    (generally with wildcard characters), then the statement is not applied\n"
		"    immediately but is stored for use during rule expansion; during rule\n"
		"    expansion, it is applied to all species that match the given species\n"
		"    pattern."},
	{"statement","Statements about molecules",0,"surface_drift surface_drift_rule",
		"  surface_drift species(state) surface panel-shape float_0 ... float_(dim-2)\n"
		"  surface_drift_rule species(state) surface panel-shape float_0 ... float_(dim-2)",
		"    Drift velocity vector for molecules of type species and state state,\n"
		"    relative to the local coordinates of the panel to which these molecules are\n"
		"    bound. The vector has dim-1 terms (dim is the system dimensionality), which\n"
		"    are for the natural coordinate system of the local panel. species and/or\n"
		"    state may be \"all\" to set drift vectors for multiple species and\n"
		"    surface-bound states at once. If the rule form is used (generally with\n"
		"    wildcard characters), then the statement is not applied immediately but is\n"
		"    stored for use during rule expansion; during rule expansion, it is applied\n"
		"    to all species that match the given species pattern."},
	{"statement","Statements about molecules",0,"mol",
		"  mol nmol species pos_0 pos_1 ... pos_(dim-1)",
		"    Simulation starts with nmol type species molecules at location pos. Each of\n"
		"    the dim elements of the position may be: (1) a number to give the actual\n"
		"    position of the molecule or molecules, or (2) the letter \"u\" to indicate\n"
		"    that the position for each molecule should be a random value between the\n"
		"    bounding walls, chosen from a uniform density, or (3) a position range\n"
		"    which is given as two numbers separated with a hyphen (math operations,\n"
		"    variables, and units are not allowed with this last option)."},
	{"statement","Statements about molecules",0,"surface_mol",
		"  surface_mol nmol species(state) surface pshape panel pos_0 pos_1 ... pos_(dim-1)\n"
		"  surface_mol nmol species(state) surface pshape panel",
		"    Creates surface-bound molecules. nmol molecules of type species are created\n"
		"    on the surface named surface, on the panel with shape pshape and name\n"
		"    panel. They are all put in state state, which can be \"front\", \"back\", \"up\",\n"
		"    or \"down\". If additional text is entered, it needs to be the Cartesian\n"
		"    coordinates of the molecules, all of which are put at the same spot and on\n"
		"    the same panel. If the coordinates are not given, the molecules are placed\n"
		"    randomly on the surface with a constant density, on average. For randomly\n"
		"    placed molecules, it is permissible to enter \"all\" for the panel, the\n"
		"    pshape, and/or the surface."},
	{"statement","Statements about molecules",0,"compartment_mol",
		"  compartment_mol nmol species compartment",
		"    Creates nmol solution-phase molecules of type species in the compartment\n"
		"    named compartment."},
	{"statement","Statements about molecules",0,"molecule_lists",
		"  molecule_lists listname_1 listname_2 ...",
		"    Creates and names a set of molecule lists, for molecules that are in the\n"
		"    system. This statement may be called multiple times."},
	{"statement","Statements about molecules",0,"mol_list mol_list_rule",
		"  mol_list species listname\n"
		"  mol_list species(state) listname\n"
		"  mol_list_rule species(state) listname",
		"    Assigns all molecules that are in the system and of type species and state\n"
		"    state (if state is not specified, then only the solution state is assigned)\n"
		"    to the list called listname. If the rule form is used (generally with\n"
		"    wildcard characters), then the statement is not applied immediately but is\n"
		"    stored for use during rule expansion; during rule expansion, it is applied\n"
		"    to all species that match the given species pattern."},
	{"statement","Statements about molecules",0,"max_mol",
		"  max_mol int",
		"    Optional statement (it was required up to version 2.22). This tells Smoldyn\n"
		"    to terminate if more than this many molecules end up being used for the\n"
		"    simulation."},
	{"statement","Statements about graphics",0,"graphics",
		"  graphics str",
		"    Type of graphics to use during the simulation. The options are \"none\" for\n"
		"    no graphics, \"opengl\" for basic and fast OpenGL graphics, \"opengl_good\" for\n"
		"    fair quality OpenGL graphics, and \"opengl_better\" for pretty good graphics.\n"
		"    Runtime gets slower with better quality. If this line is not entered, no\n"
		"    graphics are shown."},
	{"statement","Statements about graphics",0,"graphic_iter",
		"  graphic_iter int",
		"    Number of time steps that should be run between each update of the\n"
		"    graphics. Default value is 1."},
	{"statement","Statements about graphics",0,"graphic_delay",
		"  graphic_delay float",
		"    Minimum amount of time in milliseconds that Smoldyn should pause between\n"
		"    successive graphics updates. Default is 0."},
	{"statement","Statements about graphics",0,"quit_at_end",
		"  quit_at_end yes/no",
		"    Whether Smoldyn should quit running as soon as the simulation is complete\n"
		"    or not. Enter yes (or 1) if it should and no (or 0) if not. The same\n"
		"    behavior can be achieved by creating and setting the shell environment\n"
		"    variable SMOLDYN_NO_PROMPT."},
	{"statement","Statements about graphics",0,"frame_thickness",
		"  frame_thickness int",
		"    Thickness of the frame that is drawn around the simulation volume, in\n"
		"    points. Default value is 2."},
	{"statement","Statements about graphics",0,"frame_color",
		"  frame_color color [alpha]\n"
		"  frame_color red green blue [alpha]",
		"    Color of the frame. All values should be between 0 and 1; use all 0s for\n"
		"    black and all 1s for white (default). The alpha value is optional and also\n"
		"    useless."},
	{"statement","Statements about graphics",0,"grid_thickness",
		"  grid_thickness int",
		"    Thickness of the grid lines that can be drawn to show the virtual boxes.\n"
		"    Default value is 0, so that the grid is not drawn."},
	{"statement","Statements about graphics",0,"grid_color",
		"  grid_color color [alpha]\n"
		"  grid_color red green blue [alpha]",
		"    Color of the grid. All values should be between 0 and 1; use all 0s for\n"
		"    black and all 1s for white (default). The alpha value is optional and also\n"
		"    useless."},
	{"statement","Statements about graphics",0,"background_color",
		"  background_color color [alpha]\n"
		"  background_color red green blue [alpha]",
		"    Color of the background. All values should be between 0 and 1; use all 0s\n"
		"    for black and all 1s for white (default). The alpha value is optional and\n"
		"    may not work anyhow."},
	{"statement","Statements about graphics",0,"display_size display_size_rule",
		"  display_size species float\n"
		"  display_size species(state) float\n"
		"  display_size_rule species(state) float",
		"    Size of molecule of type species for display to the graphical output. If\n"
		"    the surface state is omitted, as in the first form shown, this display size\n"
		"    applies to all molecule states; otherwise it applies to only the state\n"
		"    listed. These states may be \"solution\", \"front\", \"back\", \"up\", \"down\", or\n"
		"    \"all\". The default value is 3, indicating that each molecule is displayed\n"
		"    with a small square; 0 indicates that a molecule should not be displayed\n"
		"    and larger numbers yield larger squares. If the rule form is used\n"
		"    (generally with wildcard characters), then the statement is not applied\n"
		"    immediately but is stored for use during rule expansion; during rule\n"
		"    expansion, it is applied to all species that match the given species\n"
		"    pattern."},
	{"statement","Statements about graphics",0,"color color_rule",
		"  color species(state) color [alpha]\n"
		"  color species(state) red green blue [alpha]\n"
		"  color_rule species(state) red green blue [alpha]",
		"    Color for displaying molecules of type species. If the surface state is\n"
		"    omitted, this color applies to just the solution state. States may be\n"
		"    \"solution\", \"front\", \"back\", \"up\", \"down\", or \"all\". Colors can be words,\n"
		"    or can be given with red, green, and blue values, each of which should be\n"
		"    between 0 and 1. Default values are 0 for each parameter, which is black.\n"
		"    Entering alpha is optional and useless. If the rule form is used (generally\n"
		"    with wildcard characters), then the statement is not applied immediately\n"
		"    but is stored for use during rule expansion; during rule expansion, it is\n"
		"    applied to all species that match the given species pattern."},
	{"statement","Statements about graphics",0,"tiff_iter",
		"  tiff_iter int",
		"    Number of time steps that should be run between each automatic saving of a\n"
		"    TIFF file. Default value is 0, meaning that TIFFs should not be saved\n"
		"    automatically."},
	{"statement","Statements about graphics",0,"tiff_name",
		"  tiff_name name",
		"    Root filename for TIFF files, which may include path information if\n"
		"    desired. Default is OpenGL, which leads to the first TIFF being saved as\n"
		"    \"OpenGL001.tif\"."},
	{"statement","Statements about graphics",0,"tiff_min",
		"  tiff_min int",
		"    Initial suffix number of TIFF files that are saved. Default value is 1."},
	{"statement","Statements about graphics",0,"tiff_max",
		"  tiff_max int",
		"    Largest possible suffix number of TIFF files that are saved. Once this\n"
		"    value has been reached, additional TIFFs cannot be saved. Default value is\n"
		"    999."},
	{"statement","Statements about graphics",0,"light",
		"  light number parameter value_1 value_2 value_3 [value_4]",
		"    Set the parameters for a light source, for use with \"opengl_better\" quality\n"
		"    graphics. The light number should be between 0 and 7 for which light is\n"
		"    being set. It can also be either \"global\" or \"room\", which are the same\n"
		"    thing and set the ambient room lights, which are non-directional; use the\n"
		"    \"ambient\" parameter for the room light. The parameter may be one of the\n"
		"    strings: \"ambient\", \"diffuse\", \"specular\", \"position\", \"on\", \"off\", or\n"
		"    \"auto\". For \"ambient\", \"diffuse\", and \"specular\", enter the color with the\n"
		"    value inputs for red, green, and blue color channels; optionally, end with\n"
		"    alpha. Ambient light is non-directional and does not reflect off of a\n"
		"    surface. Diffuse light is directional (from the light source) but lights\n"
		"    the illuminated side of a surface evenly, as though it is a non-shiny\n"
		"    surface. Specular light is also directional and reflects off of a surface\n"
		"    as though it is shiny.\n"
		"\n"
		"    For parameter type \"position\", either enter the light's 3-dimensional\n"
		"    position as x, y, and z in the values and then enter a value of 1 for the\n"
		"    fourth value; or, enter the vector that the light points in using the x, y,\n"
		"    and z values, keeping each between 0 and 1, and then enter the fourth value\n"
		"    as 0. Lights specified this way are automatically enabled (turned on). You\n"
		"    can also turn a light on or off with parameter of \"on\" or \"off\". The \"auto\"\n"
		"    parameter produces a low white light source; if used for the room, then\n"
		"    this is ambient light and if used for a specific light, then this is a mix\n"
		"    of diffuse and specular light."},
	{"statement","Statements about graphics",0,"text_color",
		"  text_color color\n"
		"  text_color red green blue",
		"    Color for text displayed on the graphics window."},
	{"statement","Statements about graphics",0,"text_display",
		"  text_display item_1 item_2 ...",
		"    Turns on text display of the listed items, which are listed as strings.\n"
		"    Possible items are \"time\", which is the simulation time, and species names\n"
		"    and states (entered as species(state)), for which the number of molecules\n"
		"    of that species and state are displayed. Wildcards are permitted."},
	{"statement","Statements about run-time commands",0,"output_root",
		"  output_root str",
		"    Root of path where text output should be saved. Spaces are permitted.\n"
		"    Output files are saved in the same folder as the configuration file,\n"
		"    modified by this string. See the description for output_files. Make sure\n"
		"    that the destination folder has been created and that the string is\n"
		"    terminated with a colon (and started with a colon if needed)."},
	{"statement","Statements about run-time commands",0,"output_files",
		"  output_files str_1 str_2 ... str_n",
		"    Declaration of filenames that can be used for output of simulation results.\n"
		"    Spaces are not permitted in these names. Any previous files with these\n"
		"    names will be overwritten. The path for these filenames starts from the\n"
		"    configuration file and may be modified by a root given with output_root.\n"
		"    For example, if the configuration file was called with \"folder/config.txt\"\n"
		"    and output_root was not used, then the output file \"out.txt\" will appear in\n"
		"    the directory \"folder\" too. If the configuration file was called with\n"
		"    \"folder/config.txt\" and the output root was given as \"results/\", then the\n"
		"    output file goes to the results sub-directory of the directory \"folder\".\n"
		"    The filename \"stdout\" results in output being sent to the standard output\n"
		"    (this does not need to be declared with the output_files statement)."},
	{"statement","Statements about run-time commands",0,"output_data",
		"  output_data str_1 str_2 ... str_n",
		"    Declaration of data names that can be used for output of simulation\n"
		"    results. These are like output files but are stored in memory rather than\n"
		"    as separate files, and they go away when Smoldyn ends. These data files are\n"
		"    primarily designed for use with Libsmoldyn, as opposed to the stand-alone\n"
		"    software."},
	{"statement","Statements about run-time commands",0,"output_precision",
		"  output_precision int",
		"    The precision that will be used for numerical output from commands, meaning\n"
		"    the number of digits displayed after a decimal point. Enter a negative\n"
		"    number for the default and a positive number for fixed precision. For\n"
		"    example, if you enter 5, then the output format string will be \"%.5g\"."},
	{"statement","Statements about run-time commands",0,"append_files",
		"  append_files str_1 str_2 ... str_n",
		"    Identical to output_file, except that the prior contents of these files are\n"
		"    not overwritten, but are appended to."},
	{"statement","Statements about run-time commands",0,"output_file_number",
		"  output_file_number int",
		"    Starting number of output file name. The default is 0, meaning that no\n"
		"    number is appended to a name (e.g. the file name \"out.txt\" is saved as\n"
		"    \"out.txt\"). A value larger than 0 leads to an appended file name (if 1 is\n"
		"    used, then \"out.txt\" is actually saved as \"out_001.txt\"). Note that the\n"
		"    command incrementfile increments the file number before it runs the rest of\n"
		"    the command."},
	{"statement","Statements about run-time commands",0,"output_format",
		"  output_format str",
		"    Set the output format for all observation commands. Options are the string\n"
		"    \"ssv\", which is the default, or the string \"csv\"."},
	{"statement","Statements about run-time commands",0,"cmd",
		"  cmd b,a,e string\n"
		"  cmd @ time string\n"
		"  cmd n int string\n"
		"  cmd i on off dt string\n"
		"  cmd j on_it off_it dt_it string\n"
		"  cmd x on off dt xt string",
		"    Declaration of a command to be run by the run-time interpreter, where the\n"
		"    final portion labeled string is the actual command. The character following\n"
		"    cmd is the command type, which may be \"b\" for before the simulation, \"a\"\n"
		"    for after the simulation, \"e\" for every time step during the simulation,\n"
		"    \"@\" for a single command execution at time time, \"n\" for every n'th\n"
		"    iteration of the simulation, \"i\" for a fixed time interval, \"x\" for a fixed\n"
		"    time multiplier, or \"j\" for every dt_it step with a set starting iteration\n"
		"    and stopping iteration. For type \"i\", the command is executed over the\n"
		"    period from on to off with intervals of at least dt (the actual intervals\n"
		"    will only end at the times of simulation time steps). For type \"x\", the\n"
		"    command is executed at on, then on+dt, then on+dt*xt, then on+dt*xt^2, and\n"
		"    so forth. See section 2.4 for the commands that are available."},
	{"statement","Statements about run-time commands",0,"max_cmd",
		"  max_cmd int (obsolete statement)",
		"    Maximum length of command queue. Default value is 10. As of version 1.55,\n"
		"    this statement is no longer needed in configuration files, because the\n"
		"    command queue is now expanded as needed."},
	{"statement","Statements about surfaces",0,"max_surface",
		"  max_surface int (obsolete statement)",
		"    As of version 2.19, this statement is optional. If used, it specifies the\n"
		"    maximum number of surfaces that will be defined. Each surface may have many\n"
		"    panels, including disjoint panels."},
	{"statement","Statements about surfaces",0,"start_surface",
		"  start_surface [name]",
		"    Start of surface definition block. The surface name may be given with name,\n"
		"    or it may be given afterward with the name statement. If the name has not\n"
		"    been used yet for a surface, then a new surface is started. Between this\n"
		"    instruction and end_surface, all lines need to pertain to surfaces.\n"
		"    Parameters of one surface can be listed in multiple blocks, or parameters\n"
		"    for many surfaces can be listed in one block."},
	{"statement","Statements about surfaces",0,"new_surface",
		"  new_surface name",
		"    Defines a new surface called name, but does not start a surface block. This\n"
		"    statement is largely redundant with start_surface."},
	{"statement","Statements about surfaces",1,"name",
		"  * name name",
		"    Name of the surface for editing. This statement is not required because the\n"
		"    surface name can also be given with start_surface. This statement gives the\n"
		"    name of the current surface for editing, and creates a new surface if\n"
		"    needed."},
	{"statement","Statements about surfaces",1,"action action_rule",
		"  * action species(state) face action [new_spec]\n"
		"  * action_rule species(state) face action [new_spec]",
		"    The behavior of molecules named species (and in state state, which is\n"
		"    assumed to be solution if it's not entered) when they collide with the face\n"
		"    face of this surface. face can be \"front\", \"back\", or \"both\". If species is\n"
		"    \"all\", then this action applies to all molecules. The action can be\n"
		"    \"reflect\", \"absorb\", \"transmit\", \"jump\", \"port\", or \"periodic.\" If new_spec\n"
		"    is entered, then the molecule changes to this new species upon surface\n"
		"    collision. In addition, it's permissible to enter the action as \"multiple,\"\n"
		"    in which case the rates need to be set with rate; alternatively, just\n"
		"    setting the rates will automatically set the action to \"multiple.\" The\n"
		"    default is transmission for all molecules. If the rule form is used\n"
		"    (generally with wildcard characters), then the statement is not applied\n"
		"    immediately but is stored for use during rule expansion; during rule\n"
		"    expansion, it is applied to all species that match the given species\n"
		"    pattern."},
	{"statement","Statements about surfaces",1,"rate rate_rule",
		"  * rate species(state) state_1 state_2 value [new_spec]\n"
		"  * rate_rule species(state) state_1 state_2 value [new_spec]",
		"    The rate constant for transitions from state_1 to state_2 of molecules\n"
		"    named species at this surface. For the species name, in species, \"all\" is\n"
		"    permitted; however, \"all\" is not permitted anywhere else. Usually, state is\n"
		"    omitted, but see below for where it is needed. state_1 and state_2 can be\n"
		"    any of: fsoln, bsoln (in solution, hitting the front or back of the panel,\n"
		"    respectively), front, back, up, or down. value is the rate constant or rate\n"
		"    coefficient; enter it as -1 if you want the maximum possible value,\n"
		"    typically meaning that the probability gets set to 1 (however, it may get\n"
		"    set to a lower value if the rate of the reverse process is also set to -1,\n"
		"    in which case both probabilities are chosen to maintain the appropriate\n"
		"    equilibrium constant). If new_spec, which is an optional parameter, is\n"
		"    entered, then molecules change to the listed species at the same time as\n"
		"    changing states. If the rule form is used (generally with wildcard\n"
		"    characters), then the statement is not applied immediately but is stored\n"
		"    for use during rule expansion; during rule expansion, it is applied to all\n"
		"    species that match the given species pattern.\n"
		"\n"
		"    To specify interaction rates for molecules that collide with surface B,\n"
		"    while diffusing along surface A, use the first state parameter. In this\n"
		"    case: state is the starting surface-bound state on surface A; state_1 is\n"
		"    fsoln to indicate collision with the front side of surface B or bsoln to\n"
		"    indicate collision with the back side of surface B; and state_2 is fsoln or\n"
		"    bsoln to indicate transmission through surface B and still bound to surface\n"
		"    A (but cannot equal state_1) or state_2 can be a surface-bound state to\n"
		"    indicate that the molecule hops from surface A to surface-bound on surface\n"
		"    B."},
	{"statement","Statements about surfaces",1,"rate_internal rate_internal_rule",
		"  * rate_internal species(state) state_1 state_2 value [new_spec]\n"
		"  * rate_internal_rule species(state) state_1 state_2 value [new_spec]",
		"    This is identical to rate, except that a slightly different value is\n"
		"    entered. Instead of entering the surface action rate, enter the probability\n"
		"    of the action at each collision. Probabilities for reflection are ignored\n"
		"    since they are calculated as the probability that the molecule does not\n"
		"    transmit, absorb, or jump. If the rule form is used (generally with\n"
		"    wildcard characters), then the statement is not applied immediately but is\n"
		"    stored for use during rule expansion; during rule expansion, it is applied\n"
		"    to all species that match the given species pattern."},
	{"statement","Statements about surfaces",1,"neighbor_action",
		"  *neighbor_action action",
		"    Behavior of surface-bound molecules when they collide with a panel that is\n"
		"    a neighbor of the panel that they are bound to. There are only two options:\n"
		"    \"hop\" indicates that the molecule should hop onto the new panel with a 50%\n"
		"    probability and stay with a 50% probability, and \"stay\" indicates that the\n"
		"    molecule should stay on its own surface. The default is \"stay\"."},
	{"statement","Statements about surfaces",1,"color",
		"  * color face color [alpha]\n"
		"  * color face red green blue [alpha]",
		"    Color of the face face of the surface. face can be \"front\", \"back\", or\n"
		"    \"both\". In the first format, color is a single word color, such as \"red\",\n"
		"    \"green\", \"magenta\", \"cyan\", etc. In the second format, color values are\n"
		"    numbers between 0 and 1, where 1 is maximum intensity a 0 is minimum (1 1 1\n"
		"    is white). The alpha value is optional and describes the opacity of the\n"
		"    surface. If entered, it also needs to be between 0 and 1, where 1 is an\n"
		"    opaque object (the default) and 0 is transparent. OpenGL graphics do not\n"
		"    work well with non-integer alpha values, so don't expect good results."},
	{"statement","Statements about surfaces",1,"thickness",
		"  * thickness float",
		"    Boldness of the surface in pixels for drawing purposes. This is only\n"
		"    relevant for 1-D and 2-D simulations, and for 3-D simulations in which\n"
		"    surfaces are drawn with just vertices or edges and not faces."},
	{"statement","Statements about surfaces",1,"stipple",
		"  * stipple factor pattern",
		"    Stippling of the surface edges, for drawing purposes. This is only relevant\n"
		"    for 3-D simulations in which surfaces are drawn with just edges and not\n"
		"    faces, and with \"opengl_good\" or better display method. In factor, which is\n"
		"    an integer, enter the repeat distance for the entire stippling pattern (1\n"
		"    is a good choice). In pattern, which is a hexadecimal integer, enter the\n"
		"    stippling pattern between 0x0000 and 0xFFFF. 0x00FF has long dashes, 0x0F0F\n"
		"    has medium dashes, 0x5555 has dots, etc. Turn stippling off with 0xFFFF."},
	{"statement","Statements about surfaces",1,"polygon",
		"  * polygon face drawmode",
		"    Drawing method for the face face of the surface. face can be \"front\",\n"
		"    \"back\", or \"both\". drawmode may be \"none\", \"vertex\", \"edge\", \"face\", or\n"
		"    combinations of \"v\", \"e\", or \"f\" for multiple renderings of vertices,\n"
		"    edges, and/or faces. 2-D spheres and hemispheres are either filled or are\n"
		"    outlined depending on the polygon front character. If multiple renderings\n"
		"    are chosen in 3D, then panel faces are shown in the requested color and\n"
		"    other renderings are shown in black."},
	{"statement","Statements about surfaces",1,"shininess",
		"  * shininess face value",
		"    Shininess of the surface for drawing purposes. This value can range from 0\n"
		"    for visually flat surfaces to 128 for very shiny surfaces. This is only\n"
		"    relevant for some simulations."},
	{"statement","Statements about surfaces",1,"max_panels",
		"  * max_panels shape int (obsolete statement)",
		"    Optional statement. This can be used to allocate memory for int panels of\n"
		"    shape shape for this surface, although it is usually best to let Smoldyn\n"
		"    allocate memory as needed. The shape may be \"rect\" for a rectangle, \"tri\"\n"
		"    for a triangle, \"sph\" for a sphere, \"cyl\" for a cylinder, \"hemi\" for a\n"
		"    hemisphere, or \"disk\" for a disk. The surface can include panels with\n"
		"    different shapes."},
	{"statement","Statements about surfaces",1,"panel",
		"  * panel shape float ... float [name]",
		"    Defines a new panel for the surface, where the panel has shape shape. The\n"
		"    shape may be \"rect\" for a rectangle, \"tri\" for a triangle, \"sph\" for a\n"
		"    sphere, \"cyl\" for a cylinder, \"hemi\" for a hemisphere, or \"disk\" for a\n"
		"    disk. Following the shape are numbers for the panel position, where these\n"
		"    depend on the shape. At the end, it is possible to enter a string to name\n"
		"    the panel, although this is optional (default names are the numbers 0, 1,\n"
		"    2, ...; names are used for jump surfaces). If the name was used before,\n"
		"    then this does not create a new panel, but modifies the existing panel.\n"
		"\n"
		"    For \"rect\", enter the axis number that the rectangle is perpendicular to,\n"
		"    preceded by a \"+\" if the panel front faces the positive axis and a \"-\" if\n"
		"    it faces the negative axis (these signs must be entered); then enter the\n"
		"    coordinates of a corner point; then enter the dimensions of the rectangle\n"
		"    in sequential order of the axes, omitting the one that it is perpendicular\n"
		"    to. These dimensions are better called displacements because they are added\n"
		"    to the corner that is entered, so they may be positive or negative. For\n"
		"    example, for a square in a 3-D system that is perpendicular to the y-axis,\n"
		"    has sides of length 10 and is centered about the origin, enter: \"panel rect\n"
		"    +1 -5 0 -5 10 10\". This same square could be entered as \"panel rect +1 5 0\n"
		"    5 -10 -10\", or with other descriptions. A rectangle is always perpendicular\n"
		"    to an axis.\n"
		"\n"
		"    For \"tri\", enter the coordinates of the corners of the triangle. This is\n"
		"    one number for 1-D; 4 for 2-D, and 9 for 3-D. For 1-D, the front of the\n"
		"    triangle always faces the positive axis; rectangles are completely\n"
		"    equivalent and more versatile. For 2-D, triangles are really lines and the\n"
		"    front side of the line is the side on the right when traveling in\n"
		"    sequential order of the points that are entered. For 3-D, the triangle\n"
		"    front is determined by the winding direction of the corners: if one is\n"
		"    facing the front, the points wind counterclockwise. Unlike rectangles,\n"
		"    triangles do not have to be perpendicular to axes.\n"
		"\n"
		"    For \"sph\", enter the coordinates of the sphere center followed by the\n"
		"    sphere radius and some drawing information. For 1-D, the center coordinate\n"
		"    is a single number and the radius is entered next. For 2-D, the center\n"
		"    coordinates are 2 numbers and then enter the radius followed by the number\n"
		"    of sides on the polygon that should be drawn to represent the circle. For\n"
		"    3-D, the center coordinates are 3 numbers and then enter the radius,\n"
		"    followed by the number of slices (longitude lines) and stacks (latitude\n"
		"    lines) that are used for drawing the sphere. In the 2-D and 3-D cases, the\n"
		"    drawing entries are used only for drawing; the circle or sphere functions\n"
		"    as an accurate smooth shape. For all dimensions, enter a positive radius to\n"
		"    have the front of the surface on the outside and a negative radius for it\n"
		"    to be on the inside.\n"
		"\n"
		"    For \"cyl\", enter the coordinates of the cylinder-axis start point and the\n"
		"    cylinder-axis end point, then the radius, and then drawing information if\n"
		"    appropriate. Cylinders are not permitted in 1-D. In 2-D, two numbers give\n"
		"    the start point and two give the end point, followed by the radius. No\n"
		"    drawing information is needed. In 3-D, enter three numbers for the start\n"
		"    point, three for the end point, the radius, and then the number of slices\n"
		"    and the number of stacks. For all dimensions, enter a positive radius to\n"
		"    have the front of the surface on the outside and a negative radius for it\n"
		"    to be on the inside.\n"
		"\n"
		"    For \"hemi\", enter the coordinates of the hemisphere center, the radius, and\n"
		"    then the vector that points straight out of the hemisphere. Hemispheres are\n"
		"    not permitted in 1-D. In 2-D, the center coordinates are 2 numbers, the\n"
		"    radius is 1 number, the outward vector is 2 numbers, and finally enter the\n"
		"    number of slices. For 3-D, the center is 3 numbers, the radius is 1 number,\n"
		"    the outward vector is 3 numbers, and then enter 2 numbers for the numbers\n"
		"    of slices and stacks. The outward pointing vector does not need to be\n"
		"    normalized to unit length. For all dimensions, enter a positive radius to\n"
		"    have the front of the surface on the outside and a negative radius for it\n"
		"    to be on the inside.\n"
		"\n"
		"    For \"disk\", enter the coordinates of the disk center, the radius, a vector\n"
		"    that points away from the front of the disk, and drawing information if\n"
		"    appropriate. Disks are not permitted in 1-D. In 2-D, the center coordinates\n"
		"    are 2 numbers, the radius is 1 number, and the normal vector is 2 numbers.\n"
		"    For 3-D, the center coordinates are 3 numbers, the radius is 1 number, the\n"
		"    normal vector is 3 numbers, and the number of drawing slices is entered\n"
		"    last. Normal vectors do not need to have unit length."},
	{"statement","Statements about surfaces",1,"jump",
		"  * jump panel_1 face_1 -> panel_2 face_2\n"
		"  * jump panel_1 face_1 <-> panel_2 face_2",
		"    Defines a molecule jumping condition for a face of a single panel. This\n"
		"    panel has name panel_1, and face face_1. The name of a panel can be defined\n"
		"    with the panel statement, or the default is just the shape and panel number\n"
		"    (rect0, sph5, etc.). A molecule that hits this face of the panel, and that\n"
		"    has \"jump\" action for this face, gets translated to the face face_2 of the\n"
		"    panel panel_2 (which needs to be the same shape as the originating panel).\n"
		"    A unidirectional arrow implies just jumping from the first panel to the\n"
		"    second, whereas a double-headed arrow implies jumping in both directions."},
	{"statement","Statements about surfaces",1,"neighbors",
		"  * neighbors panel neigh_1 neigh_2 ...",
		"    Defines a list of panels that neighbor the panel named panel. Surface-bound\n"
		"    molecules can only diffuse from a panel to its neighbor if the neighbors\n"
		"    are defined in this way. This statement is unidirectional in that it only\n"
		"    sets, for example, neigh_1 as a neighbor of panel panel but not vice versa.\n"
		"    If the neighboring panel is not part of the same surface as the origin\n"
		"    panel, then specify the neighboring panel using surface:panel."},
	{"statement","Statements about surfaces",1,"unbounded_emitter",
		"  * unbounded_emitter face species amount pos_0 pos_1 ... pos_(dim-1)",
		"    Declares a molecular source for which this surface should absorb molecules\n"
		"    so as to yield a concentration distribution that is the same as that which\n"
		"    would arise with unbounded diffusion. This statement does not create the\n"
		"    molecular source, but only sets the panel absorption coefficients to yield\n"
		"    the correct concentrations, assuming the emitter is created elsewhere (such\n"
		"    as with a command or a zeroth order reaction). face is the side of the\n"
		"    surface that faces the emitter, species is the emitted molecular species,\n"
		"    amount is the emission rate (it only matters if there is more than one\n"
		"    emitter for this surface and species, and then it is only the relative\n"
		"    rates of the different emitters that matters), and pos is the\n"
		"    system-dimensional position of the emitter. This statement is designed to\n"
		"    be used with all emitters strictly inside a closed surface and all of them\n"
		"    with positive amount values."},
	{"statement","Statements about surfaces",1,"end_surface",
		"  * end_surface",
		"    End of a block of surface definitions. Surface statements are no longer\n"
		"    recognized but other simulation statements are."},
	{"statement","Statements about surfaces",0,"epsilon",
		"  epsilon float",
		"    See \"simulation settings\" section. This is not entered in a surface block."},
	{"statement","Statements about surfaces",0,"margin",
		"  margin float",
		"    See \"simulation settings\" section. This is not entered in a surface block."},
	{"statement","Statements about surfaces",0,"neighbor_dist",
		"  neighbor_dist float",
		"    See \"simulation settings\" section. This is not entered in a surface block."},
	{"statement","Statements about compartments",0,"start_compartment",
		"  start_compartment name",
		"    Start of compartment definition block. The compartment name may be given\n"
		"    with name, or it may be given afterwards with the name statement. If the\n"
		"    name has not been used yet for a compartment, then a new compartment is\n"
		"    started. Between this instruction and end_compartment, all lines need to\n"
		"    pertain to compartments. Parameters of one compartment can be listed in\n"
		"    multiple blocks, or parameters for many compartments can be listed in one\n"
		"    block."},
	{"statement","Statements about compartments",0,"new_compartment",
		"  new_compartment name",
		"    Defines a new compartment called name, but does not start a compartment\n"
		"    block. This statement is largely redundant with start_compartment."},
	{"statement","Statements about compartments",1,"name",
		"  * name name",
		"    Name of the compartment for editing. This statement is not required because\n"
		"    the compartment name can also be given with start_compartment. This\n"
		"    statement gives the name of the current compartment for editing, and\n"
		"    creates a new compartment if needed."},
	{"statement","Statements about compartments",1,"surface",
		"  * surface surface",
		"    Name of a bounding surface for this compartment."},
	{"statement","Statements about compartments",1,"point",
		"  * point pos_0 ... pos_(dim-1)",
		"    An interior-defining point for this compartment."},
	{"statement","Statements about compartments",1,"compartment",
		"  * compartment logic compartment",
		"    Logically combines the compartment being defined as it has been defined so\n"
		"    far with the compartment that is listed in this statement. The logic\n"
		"    options are: \"equal\", \"equalnot\", \"and\", \"andnot\", \"or\", \"ornot\", and\n"
		"    \"xor\"."},
	{"statement","Statements about compartments",1,"end_compartment",
		"  * end_compartment",
		"    End of a block of compartment definitions. Compartment statements are no\n"
		"    longer recognized but other simulation statements are."},
	{"statement","Statements about reactions",0,"reaction",
		"  reaction rname reactant_1 + reactant_2 -> product_1 + product_2 rate\n"
		"  reaction rname reactant_1 + reactant_2 <-> product_1 + product_2 ratefwd raterev\n"
		"  reaction compartment=cname rname reactant_1 + reactant_2 -> product_1 + product_2 rate\n"
		"  reaction surface=sname rname reactant_1 + reactant_2 -> product_1 + product_2 rate",
		"    The first form defines a new reaction which is named rname, has a list of\n"
		"    reactants, a list of products, and rate equal to rate. If there are no\n"
		"    reactants, meaning that it is zeroth order, enter \"0\" as the reactant.\n"
		"    Similarly, if there are no products, enter \"0\" as the sole product. The\n"
		"    rate value is optional. As usual, enter species states in parentheses after\n"
		"    the species names; \"all\" is permitted for reactant states, but not for\n"
		"    product states.\n"
		"\n"
		"    The second form shows that reversible reactions can be defined using\n"
		"    essentially the same statement, but with <-> for the arrow and, optionally,\n"
		"    with two rate constants. In this case, the reaction name is appended with\n"
		"    \"fwd\" for the forward reaction and with \"rev\" for the reverse reaction.\n"
		"    Entering a reversible reaction in this way is completely equivalent to\n"
		"    entering it as two one-way reactions; it has no effect on the product\n"
		"    placement, the binding radius, or other parameters.\n"
		"\n"
		"    If this reaction should only occur in a specific compartment, enter it with\n"
		"    the format \"compartment=cname\" (no spaces) as one of the first parameters.\n"
		"    Likewise, if this reaction should only occur on a specific surface, enter\n"
		"    it with the format \"surface=sname\" as one of the first parameters. These\n"
		"    restrictions can be combined."},
	{"statement","Statements about reactions",0,"reaction_rule",
		"  reaction_rule rname reactant_1 + reactant_2 -> product_1 + product_2 rate",
		"    This is essentially identical to the reaction statement, including that it\n"
		"    allows the same reversibility notation and compartment and surface\n"
		"    restrictions. It differs in that any products that are listed here but that\n"
		"    have not been declared previously using the species statement, get created\n"
		"    at this point. When used with wildcards, this statement enables rule-based\n"
		"    modeling."},
	{"statement","Statements about reactions",0,"reaction_rate",
		"  reaction_rate rname rate",
		"    Sets the rate constant to rate for reaction named rname."},
	{"statement","Statements about reactions",0,"reaction_multiplicity",
		"  reaction_multiplicity rname multiplicity",
		"    Sets the multiplicity value to multiplicity for reaction named rname. This\n"
		"    value is set to 1 by default, but can be changed if there are multiple\n"
		"    different ways for a single reaction to occur. The requested reaction rate\n"
		"    is multiplied by the multiplicity to give the total reaction rate.\n"
		"    Internally, this is an important parameter for rule-based modeling, but the\n"
		"    value should generally not be set using this statement."},
	{"statement","Statements about reactions",0,"confspread_radius",
		"  confspread_radius rname rad",
		"    Defines reaction rname as a conformational spread reaction. This reaction\n"
		"    must have two reactants and up to two products. If it has two products,\n"
		"    which is the most common case, then the first reactant gets replaced by the\n"
		"    first product, and the second with the second. They keep their serial\n"
		"    numbers and locations. The reaction domain extends over the radius that is\n"
		"    listed here (this is effectively a binding radius). If this is entered, the\n"
		"    reaction rate constant is interpreted as a first order rate constant."},
	{"statement","Statements about reactions",0,"binding_radius",
		"  binding_radius rname rad",
		"    Sets the binding radius of reaction rname to rad."},
	{"statement","Statements about reactions",0,"reaction_probability",
		"  reaction_probability rname prob",
		"    A fixed probability value for unimolecular or bimolecular reactions. For\n"
		"    unimolecular reactions, this is the probability of a reaction during one\n"
		"    time step. For bimolecular reactions, this is the probability of a reaction\n"
		"    occurring, given that the reactants are already closer than their binding\n"
		"    radius. Here, the default value is 1, which is assumed in all rate\n"
		"    calculations. For conformational spread reactions, this value can be used\n"
		"    to directly enter the reaction probability at each time step, rather than\n"
		"    letting it be calculated from the rate value. For regular bimolecular\n"
		"    reactions, this can be used to adjust the effective reaction activation\n"
		"    energy, although the theory has not been derived for that yet."},
	{"statement","Statements about reactions",0,"reaction_chi",
		"  reaction_chi rname chi",
		"    The diffusion-limited fraction (chi) of a bimolecular reaction. This value\n"
		"    is the ratio of the actual reaction rate constant to the diffusion-limited\n"
		"    reaction rate constant."},
	{"statement","Statements about reactions",0,"reaction_production",
		"  reaction_production rname value",
		"    Molecule production rate for zeroth order reactions. Instead of entering\n"
		"    the reaction rate with reaction_rate, this allows one to enter the\n"
		"    expectation number of molecules per time step in the entire simulation\n"
		"    volume."},
	{"statement","Statements about reactions",0,"product_placement",
		"  product_placement rname type parameters",
		"    Placement method and parameters for the products of reaction rname. This\n"
		"    also affects the binding radius of the reverse reaction, as explained in\n"
		"    the text. The type irrev requires no parameters. Types \"pgem\", \"pgemmax\",\n"
		"    \"pgemmaxw\", \"ratio\", \"unbindrad\", \"pgem2\", \"pgemmax2\", and \"ratio2\" each\n"
		"    require one parameter. Types \"offset\" and \"fixed\" each require first a\n"
		"    product molecule name and then a dim-dimensional vector as the parameter\n"
		"    list. If multiple products are identical, then this placement instruction\n"
		"    will only be applied to the first of the identical products. For this\n"
		"    reason, you can also specify that this statement applies to the n'th\n"
		"    product by entering the product name as product_n (e.g. product_2 for the\n"
		"    second product). The default placement method for reversible reactions is\n"
		"    \"pgemmaxw\" (the terminal \"w\" implies that a warning will be issued) with a\n"
		"    parameter of 0.2. While it is suggested that placement types be entered\n"
		"    with full words, single letter codes work as well.\n"
		"\n"
		"    To create a \"bounce\" type reaction, for simulating excluded volume, enter\n"
		"    the type as \"bounce\". In this case, enter no parameter for the default\n"
		"    algorithm or one parameter. The default algorithm, also entered with a -1\n"
		"    parameter, performs the overlap method, in which the reactant edges get\n"
		"    separated by the same amount as they used to overlap, along their\n"
		"    separation vector (e.g. consider two reactants each of radius 1, so the\n"
		"    binding radius is set to 2; then, if the center-to-center distance is found\n"
		"    to be 1.6, the molecules get separated to make the center-to-center\n"
		"    distance equal to 2.4). Using a value of -2 performs the reflection method,\n"
		"    which appears to substantially less accurate (see the Smoldyn User's\n"
		"    Manual). Alternatively, you can use the parameter value to define the new\n"
		"    separation, which should be larger than the binding radius."},
	{"statement","Statements about reactions",0,"expand_rules",
		"  expand_rules iterations",
		"    Expands all of the current reaction rules by iterations times. Enter\n"
		"    iterations as -1 for expansion to continue until all rules are fully\n"
		"    up-to-date (which will run for a very long time and then cause a\n"
		"    termination if the rules create an infinite list of species)."},
	{"statement","Statements about reactions",0,"reaction_serialnum",
		"  reaction_serialnum rname rule_list",
		"    Define rules for product molecule serial number assignments during reaction\n"
		"    rname. There should be as many rule values as there are products for this\n"
		"    reaction. The codes can be separated by \"+\" symbols, as in the reaction\n"
		"    definition, but this isn't required. Product options include: \"new\" for a\n"
		"    new serial number (the default), \"r1\" or \"r2\" for the serial number of the\n"
		"    first or second reactant, or \"p1\" to \"p4\" for the serial number of the\n"
		"    given product, or an integer greater than zero for that value as the serial\n"
		"    number. To use two-part serial numbers, combine these with a dot, so for\n"
		"    example, r1.r2 means that serial numbers for reactants 1 and 2 should be\n"
		"    concatenated (only pairwise concatenation is supported). Specify a half of\n"
		"    a two-part serial number by suffixing the code with \"R\" for the right half\n"
		"    (the default) or \"L\" for the left half. For example, r1L and r1R are the\n"
		"    left and right halves of the serial number for reactant 1. Some of these\n"
		"    options can lead to multiple molecules having the same serial numbers,\n"
		"    which is allowed but may lead to unexpected behavior in some runtime\n"
		"    commands. This statement cannot be used together with the\n"
		"    reaction_intersurface statement for the same reaction."},
	{"statement","Statements about reactions",0,"reaction_intersurface",
		"  reaction_intersurface rname rule_list",
		"    Define rules to allow bimolecular reaction named rname to operate when its\n"
		"    reactants are on different surfaces. In general, there should be as many\n"
		"    rule values as there are products for this reaction. For each product\n"
		"    choose \"r1\" if it should be placed on the first reactant's surface or\n"
		"    relative to that surface, and \"r2\" if it should be placed on the second\n"
		"    reactant's surface or relative to that surface (the relative conditions are\n"
		"    for \"soln\" or \"bsoln\" state products). The codes can be separated by \"+\"\n"
		"    symbols, as in the reaction definition, but this isn't required. To turn\n"
		"    off intersurface reactions, which is the default behavior, give rule_list\n"
		"    as \"off\". To turn on intersurface reactions for reactions that have no\n"
		"    products, give rule_list as \"on\". This statement cannot be used together\n"
		"    with the reaction_serialnum statement for the same reaction."},
	{"statement","Statements about reactions",0,"reaction_log",
		"  reaction_log filename rxnname serial_numbers",
		"    Turns on reaction logging for all occurrences of the reaction rxnname and\n"
		"    for molecules with serial numbers that are in the serial number list. The\n"
		"    logging is sent to the file called filename. If the file is not \"stdout\",\n"
		"    then it should be declared with the output_files statement. Enter rxnname\n"
		"    as \"all\" if all reactions should be logged. Likewise, enter the serial\n"
		"    number list as \"all\" if reactions with all molecules should be logged. In\n"
		"    the logging file, the output will be a single line of text for each\n"
		"    occurrence of the reaction with the following items: the current simulation\n"
		"    time, the name of the reaction, the location of the reaction (2 numbers for\n"
		"    2D, 3 for 3D), the serial numbers of each reactant, and the serial numbers\n"
		"    of each product. If you request logging for a specific serial number, then\n"
		"    an entry will be created if a molecule with this serial number is either a\n"
		"    reactant or a product of the reaction (however, if it is the second or\n"
		"    higher product, then the log entry will be missing the prior product serial\n"
		"    numbers because these are not recorded as they are generated). A specific\n"
		"    reaction can only be logged to a single place (e.g. either standard output\n"
		"    or some file, but not both at once)."},
	{"statement","Statements about reactions",0,"reaction_log_off",
		"  reaction_log_off rxnname serial_numbers",
		"    Turns off reaction logging for the reaction rxnname and for molecules with\n"
		"    serial numbers that are listed in the serial number list. Either or both of\n"
		"    rxnname and the serial number list can be \"all\"."},
	{"statement","Statements about ports",0,"start_port",
		"  start_port name",
		"    Start of port definition block. The port name may be given with name, or it\n"
		"    may be given afterward with the name statement. If the name has not been\n"
		"    used yet for a port, then a new port is started. Between this instruction\n"
		"    and end_port, all lines need to pertain to ports. Parameters of one port\n"
		"    can be listed in multiple blocks, or parameters for many ports can be\n"
		"    listed in one block."},
	{"statement","Statements about ports",0,"new_port",
		"  new_port name",
		"    Defines a new port called name, but does not start a port block. This\n"
		"    statement is largely redundant with start_port."},
	{"statement","Statements about ports",1,"name",
		"  * name name",
		"    Name of the port for editing. This statement is not required because the\n"
		"    port name can also be given with start_port. This statement gives the name\n"
		"    of the current port for editing, and creates a new port if needed."},
	{"statement","Statements about ports",1,"surface",
		"  * surface surface",
		"    Name of the porting surface for this port."},
	{"statement","Statements about ports",1,"face",
		"  * face face",
		"    Face of the surface that is active for porting. Enter \"front\" or \"back\" for\n"
		"    face."},
	{"statement","Statements about ports",1,"end_port",
		"  * end_port",
		"    End of a block of port definitions. Port statements are no longer\n"
		"    recognized but other simulation statements are."},
	{"statement","Statements about ports",0,"max_port",
		"  max_port int (optional)",
		"    Maximum number of ports that may be defined."},
	{"statement","Statements for rule-based modeling with BioNetGen",0,"start_bng",
		"  start_bng name",
		"    Start of BioNetGen block. The name is the network name. It may be given\n"
		"    here or it may be given afterwards with the name statement. If the name has\n"
		"    not been used yet for a network, then a network is started. Between this\n"
		"    instruction and end_bng, all lines need to pertain to BioNetGen complexes.\n"
		"    Parameters of one network can be listed in multiple blocks, or parameters\n"
		"    for many networks can be listed in one block."},
	{"statement","Statements for rule-based modeling with BioNetGen",0,"end_bng",
		"  end_bng",
		"    End of a block of bng definitions. Bng statements are no longer recognized\n"
		"    but other simulation statements are."},
	{"statement","Statements for rule-based modeling with BioNetGen",0,"name",
		"  name name",
		"    Name of the bng network for editing. This statement is not required because\n"
		"    the network name can also be given with start_bng. This statement gives the\n"
		"    name of the current network for editing, and creates a new network if\n"
		"    needed."},
	{"statement","Statements for rule-based modeling with BioNetGen",0,"BNG2_path",
		"  BNG2_path path",
		"    Directory path and complete filename of BNG2.pl software. The default path\n"
		"    for Mac and Linux systems is /usr/local/bin/BioNetGen/BNG2.pl and for\n"
		"    Windows is C:\\Program Files\\Smoldyn\\BioNetGen\\BNG2.pl. The path parameter\n"
		"    is allowed to have spaces in it."},
	{"statement","Statements for rule-based modeling with BioNetGen",0,"multiply",
		"  multiply unimolecular_rate value\n"
		"  multiply bimolecular_rate value",
		"    Factor that will be multiplied with unimolecular and bimolecular reaction\n"
		"    rates that are listed in the current network. This statement is useful for\n"
		"    converting units if the rules file and Smoldyn file were written with\n"
		"    different unit systems."},
	{"statement","Statements for rule-based modeling with BioNetGen",0,"monomer monomers",
		"  monomer monomer_1 monomer_2 ...\n"
		"  monomers monomer_1 monomer_2 ...",
		"    Declares one or more monomer names. This statement is optional because\n"
		"    monomer names are also inferred from the species long names and can be\n"
		"    given using monomer_state or other monomer functions. This is primarily\n"
		"    useful for enabling the use of the \"all\" designation for monomers in other\n"
		"    monomer statements."},
	{"statement","Statements for rule-based modeling with BioNetGen",0,"monomer_difc",
		"  monomer_difc monomer difc",
		"    The diffusion coefficient for monomer called monomer. The monomer value can\n"
		"    be a single monomer or can be \"all\" for all currently declared monomers. A\n"
		"    monomer has a single diffusion coefficient, independent of its state."},
	{"statement","Statements for rule-based modeling with BioNetGen",0,"monomer_display_size",
		"  monomer_display_size monomer size",
		"    The display size for monomer called monomer. The monomer value can be a\n"
		"    single monomer or can be \"all\" for all currently declared monomers. A\n"
		"    monomer has a single display size, independent of its state."},
	{"statement","Statements for rule-based modeling with BioNetGen",0,"monomer_color",
		"  monomer_color monomer color\n"
		"  monomer_color monomer red green blue",
		"    The color for monomer called monomer. The monomer value can be a single\n"
		"    monomer or can be \"all\" for all currently declared monomers. The color can\n"
		"    be either a color word or the red, green, and blue color values. A monomer\n"
		"    has a single color, independent of its state."},
	{"statement","Statements for rule-based modeling with BioNetGen",0,"monomer_state",
		"  monomer_state monomer state",
		"    The default state for a monomer. States can be any of: soln (same as\n"
		"    fsoln), bsoln, front, back, up, and down (this list is ordered from lowest\n"
		"    to highest precedence). These states are used when Smoldyn assigns states\n"
		"    to reaction products, which are often composed of many monomers."},
	{"statement","Statements for rule-based modeling with BioNetGen",0,"expand_rules",
		"  expand_rules filename",
		"    Filename for a rules file written in the BNGL language, which should have a\n"
		"    .bngl suffix. When Smoldyn encounters this statement, Smoldyn calls BNG2.pl\n"
		"    to expand the file and save it as a .net file but does not then read the\n"
		"    result. After this line, include a read_file statement and list the\n"
		"    filename, now with a .net suffix, so that Smoldyn reads in the expanded\n"
		"    network. There is typically very little error reporting if BNG2.pl\n"
		"    encounters an error in the .bngl file. To see the errors, run Smoldyn with\n"
		"    the -v command line option, for verbose operation, and then Smoldyn will\n"
		"    display all of the BNG2.pl output."},
	{"statement","Statements about filaments",0,"start_filament_type",
		"  start_filament_type name",
		"    Start of filament type definition block. The filament type name may be\n"
		"    given with name, or it may be given afterward with the name statement. If\n"
		"    the name has not been used yet for a filament type, then a new filament\n"
		"    type is started. Between this instruction and end_filament_type, all lines\n"
		"    need to pertain to filament types. Parameters of one filament type can be\n"
		"    listed in multiple blocks, or parameters for many filament types can be\n"
		"    listed in one block."},
	{"statement","Statements about filaments",1,"name",
		"  * name name",
		"    From within a filament type definition block, this switches to a new\n"
		"    filament type and creates it if needed."},
	{"statement","Statements about filaments",1,"dynamics",
		"  * dynamics dynamics",
		"    Sets the dynamics for the filament type. Current options are: \"none\",\n"
		"    \"Euler\". These are case-insensitive."},
	{"statement","Statements about filaments",1,"color",
		"  * color color",
		"    Sets the drawing color for the filament type. Enter the color as either a\n"
		"    color description as a word or as RGBalpha values."},
	{"statement","Statements about filaments",1,"thickness",
		"  * thickness thickness",
		"    Sets the drawing thickness for the filament type. Enter this in pixels if\n"
		"    the graphics type is \"opengl\" or as an actual length value for the better\n"
		"    drawing options."},
	{"statement","Statements about filaments",1,"stipple",
		"  * stipple factor pattern",
		"    Sets the stipple pattern and factor for filament drawing. This is only\n"
		"    relevant for simulations with \"opengl_good\" or better display method. In\n"
		"    factor, which is an integer, enter the repeat distance for the entire\n"
		"    stippling pattern (1 is a good choice). In pattern, which is a hexadecimal\n"
		"    integer, enter the stippling pattern between 0x0000 and 0xFFFF. 0x00FF has\n"
		"    long dashes, 0x0F0F has medium dashes, 0x5555 has dots, etc. Turn stippling\n"
		"    off with 0xFFFF."},
	{"statement","Statements about filaments",1,"polygon",
		"  * polygon drawmode",
		"    Drawing mode for filament surfaces. Options are: \"vertex\", \"edge\", \"face\",\n"
		"    or combinations of these by using single letters for vertex, edge, and\n"
		"    face, such as \"ve\", \"vef\", etc."},
	{"statement","Statements about filaments",1,"shininess",
		"  * shininess value",
		"    Shininess of the filament for drawing purposes. This value can range from 0\n"
		"    for visually flat surfaces to 128 for very shiny surfaces. This is only\n"
		"    relevant for some simulations."},
	{"statement","Statements about filaments",1,"kT",
		"  * kT value",
		"    Set the thermal energy value, equal to Boltzmann's constant times\n"
		"    temperature. Enter this in energy units that are consistent with other\n"
		"    units in the input file. This is only used for some of the dynamics\n"
		"    options."},
	{"statement","Statements about filaments",1,"treadmill_rate",
		"  * treadmill_rate value",
		"    Some filaments treadmill, in which they drop off monomers at one end and\n"
		"    add them to the other end. Set the treadmilling rate here."},
	{"statement","Statements about filaments",1,"branch_rate",
		"  * branch_rate value",
		"    Branching rate off of the mother filament, in units of per unit length per\n"
		"    time."},
	{"statement","Statements about filaments",1,"branch_angle",
		"  * branch_angle yaw",
		"    Yaw angle for new branches off of the mother filament, which is given in\n"
		"    radians. Pitch and roll angles are always zero."},
	{"statement","Statements about filaments",1,"branch_spread",
		"  * branch_spread stddev",
		"    Standard deviation of branching angle, entered in radians. Enter 0 for\n"
		"    deterministic branching."},
	{"statement","Statements about filaments",1,"branch_segments",
		"  * branch_segments segs",
		"    Length of initial daughter filament in segments."},
	{"statement","Statements about filaments",1,"branch_force_angle",
		"  * branch_force_angle value",
		"    Yaw spring constant at the branch point."},
	{"statement","Statements about filaments",1,"branch_azimuth",
		"  * branch_azimuth string",
		"    Initial azimuth of the branch about the mother filament. Enter string as\n"
		"    \"random\" for random values of a value that is >=0 for a specific angle."},
	{"statement","Statements about filaments",1,"branch_azimuth_fix",
		"  * branch_azimuth_fix 0/1",
		"    Enter 1 to fix the branch azimuth at its initial value and 0 to allow it to\n"
		"    vary."},
	{"statement","Statements about filaments",1,"branch_force_azimuth",
		"  * branch_force_azimuth value",
		"    Azimuthal spring constant at the branch point."},
	{"statement","Statements about filaments",1,"branch_surface",
		"  * branch_surface surface distance",
		"    If branching should only be allowed close to a surface, enter the surface\n"
		"    name in surface and the maximum distance in distance."},
	{"statement","Statements about filaments",1,"branch_compartment",
		"  * branch_compartment compartment",
		"    If branching should only be allowed within a certain compartment, enter\n"
		"    that compartment name here."},
	{"statement","Statements about filaments",1,"confine_surface",
		"  * confine_surface surface force [face]",
		"    If the filament should be confined by a surface, enter that surface name\n"
		"    here in surface and the force constant for that confinement in force.\n"
		"    Afterward, there is an optional face entry. This only accepts \"front\" or\n"
		"    \"back\" but should also accept \"both\"."},
	{"statement","Statements about filaments",1,"plus_end",
		"  * plus_end end",
		"    Enter whether the front or the back of the filament is considered to be the\n"
		"    plus end. Use full word \"back\" or \"front\"."},
	{"statement","Statements about filaments",1,"elongation_rate",
		"  * elongation_rate value",
		"    This is the elongation rate at the plus end in units of length/time. This\n"
		"    is usually not used in combination with treadmilling."},
	{"statement","Statements about filaments",1,"elongation_max_length",
		"  * elongation_max_length value",
		"    Maximum filament contour length when elongation can occur. Longer filaments\n"
		"    don't elongate."},
	{"statement","Statements about filaments",1,"capping_rate",
		"  * capping_rate value",
		"    Capping rate at the plus end. Units are inverse time. Capped filaments\n"
		"    don't elongate."},
	{"statement","Statements about filaments",1,"uncapping_rate",
		"  * uncapping_rate value",
		"    Uncapping rate at the plus end. Units are inverse time. Uncapped filaments\n"
		"    can elongate."},
	{"statement","Statements about filaments",1,"mobility",
		"  * mobility value",
		"    Mobility of the nodes within the surrounding medium."},
	{"statement","Statements about filaments",1,"standard_length",
		"  * standard_length length",
		"    Relaxed length of a filament segment. It can change through stretching or\n"
		"    compression."},
	{"statement","Statements about filaments",1,"standard_angle",
		"  * standard_angle yaw\n"
		"  * standard_angle yaw pitch roll",
		"    Relaxed angles between adjacent filament segments. When facing toward the\n"
		"    filament's front end, yaw represents left-right bending, pitch represents\n"
		"    up-down bending, and roll represents rotation about the filament axis. For\n"
		"    2D simulations, only enter a single bending angle."},
	{"statement","Statements about filaments",1,"force_length",
		"  * force_length value",
		"    Stretching force constant for filament segments."},
	{"statement","Statements about filaments",1,"force_angle",
		"  * force_angle yaw\n"
		"  * force_angle yaw pitch roll",
		"    Force constants for bending and torsion."},
	{"statement","Statements about filaments",1,"end_filament_type",
		"  * end_filament_type",
		"    End of a block of filament type definitions. Filament type statements are\n"
		"    no longer recognized but other simulation statements are."},
	{"statement","Statements about filaments",0,"random_filament",
		"  random_filament type:name segments [x y phi] [thickness]\n"
		"  random_filament type:name segments [x y z phi theta psi] [thickness]",
		"    Create a new filament with random segments. It is named name, is of type\n"
		"    type, has segments number of segments, and, optionally, has its starting\n"
		"    location at (x,y,z) and initial yaw-pitch-roll angle (phi, theta, psi). For\n"
		"    2D, only enter x,y and phi. It also has optional thickness thickness."},
	{"statement","Statements about filaments",0,"start_filament",
		"  start_filament type:name",
		"    Start of filament definition block, for a filament of type type and named\n"
		"    name. If the name has not been used yet for a filament of this type, then a\n"
		"    new filament is started. Between this instruction and end_filament, all\n"
		"    lines need to pertain to filaments. Parameters of one filament can be\n"
		"    listed in multiple blocks, or parameters for many filaments can be listed\n"
		"    in one block."},
	{"statement","Statements about filaments",0,"new_filament",
		"  new_filament type:name",
		"    Defines a new filament of type type that is called name, but does not start\n"
		"    a filament block. This statement is largely redundant with start_filament."},
	{"statement","Statements about filaments",1,"name",
		"  * name type:name\n"
		"  * name name",
		"    Name of the filament for editing. This statement is not required because\n"
		"    the filament name can also be given with start_filament. This statement\n"
		"    gives the name of the current filament for editing, and creates a new\n"
		"    filament if needed."},
	{"statement","Statements about filaments",1,"first_segment",
		"  * first_segment x y length angle [thickness]\n"
		"  * first_segment x y z length yaw pitch roll [thickness]",
		"    Defines the first segment of a filament. Enter the starting location in x,\n"
		"    y, and z, the segment length in length, and its absolute orientation with\n"
		"    the angle values. For 2D, the angle is the angle from the x-axis and in 3D\n"
		"    these values are the yaw-pitch-roll values away from the x-axis. The\n"
		"    thickness value is optional."},
	{"statement","Statements about filaments",1,"add_segment",
		"  * add_segment length angle [thickness [end]]\n"
		"  * add_segment length yaw pitch roll [thickness [end]]",
		"    Add a segment to the filament, with the given length. The angles are\n"
		"    relative angles from the prior segment using yaw-pitch-roll values, and the\n"
		"    thickness is optional. The segment can be added to either end, given in\n"
		"    end, where the options are front or back."},
	{"statement","Statements about filaments",1,"remove_segment",
		"  * remove_segment end",
		"    Remove one segment from end end of the filament (\"front\" or \"back\")."},
	{"statement","Statements about filaments",1,"modify_segment",
		"  * modify_segment segment length/angle/thickness +/-/= value(s) end",
		"    This modifies the length, relative angle, position, or thickness parameters\n"
		"    for the single segment number segment. After the segment number, enter one\n"
		"    of \"length\", \"angle\", \"front_position\", or \"thickness\". Then, enter \"+\" to\n"
		"    increase the current value by the given amount, \"-\" to decrease the current\n"
		"    value by the given amount, or \"=\" to set the value to the given amount,\n"
		"    where the given amount is entered in value. For the angle option with 3D,\n"
		"    enter 3 values for yaw, pitch, and roll. For the position option, enter two\n"
		"    values for 2D and three values for 3D. Finally, for the length and angle\n"
		"    options, enter end as either \"front\" or \"back\" for which filament end gets\n"
		"    moved in the process."},
	{"statement","Statements about filaments",1,"random_segments",
		"  * random_segments number [x y phi] [thickness]\n"
		"  * random_segments number [x y z phi theta psi] [thickness]",
		"    Add number of random segments to the filament. If the filament doesn't have\n"
		"    any segments yet, then enter the front position in (x,y) for 2D or (x,y,z)\n"
		"    for 3D and also enter the front segment angle in phi for 2D and\n"
		"    (phi,theta,psi) for 3D. These position and angle values can be `u' for\n"
		"    uniform distributions. The thickness parameter is optional."},
	{"statement","Statements about filaments",1,"translate",
		"  * translate symbol x y z",
		"    Translate the filament. Set symbol to \"=\" for absolute coordinates, \"+\" for\n"
		"    relative translation in which the values are added to the current filament\n"
		"    location, and \"-\" for relative translation in the other direction."},
	{"statement","Statements about filaments",1,"copy_to",
		"  * copy_to filament",
		"    Copy the current filament to filament, which is created here if it doesn't\n"
		"    already exist; any prior data in filament is overwritten."},
	{"statement","Statements about filaments",1,"branch",
		"  * branch daughter segment [yaw pitch roll]",
		"    Create a branch off of the current filament (the mother filament). Enter\n"
		"    daughter as the name of the new branch filament (the daughter) and segment\n"
		"    as the branching position off of the mother. The yaw pitch roll angles are\n"
		"    optional. If they are entered, they are the bending angle away from the\n"
		"    mother filament. If they are not entered, then the standard bending angles\n"
		"    are taken from the filament type definition (branch_angle)."},
	{"statement","Statements about filaments",1,"sequence",
		"  * sequence sequence",
		"    Enter the sequence string for a filament."},
	{"statement","Statements about filaments",1,"node_mobility",
		"  * node_mobility node mobility",
		"    Sets a unitless node mobility factor, which is multiplied by the mobility\n"
		"    that's defined in the filament type, to give the total node mobility value.\n"
		"    Enter node as the node number, where 0 is the front of the filament.\n"
		"    Alternatively, enter node as a negative value to count from the back of the\n"
		"    filament, where -1 is the back end. The mobility value has a default value\n"
		"    of 1, and can be set to other values here. In particular, setting it to 0\n"
		"    means that the node is fixed in space."},
	{"statement","Statements about filaments",1,"end_filament",
		"  * end_filament",
		"    End of a block of filament definitions. Filament statements are no longer\n"
		"    recognized but other simulation statements are."},
	{"statement","Statements about lattices",0,"start_lattice",
		"  start_lattice name",
		"    Start of the lattice block. The lattice name may be given with name, or it\n"
		"    may be given afterwards with the name statement. If the name has not been\n"
		"    used yet for a lattice, then a new lattice is started. Between this\n"
		"    statement and end_lattice, all lines need to pertain to lattices.\n"
		"    Parameters of one lattice can be listed in multiple blocks, or parameters\n"
		"    for many lattices can be listed in one block."},
	{"statement","Statements about lattices",1,"name",
		"  * name name",
		"    Name of the lattice for editing. This statement is not required because the\n"
		"    lattice name can also be given with start_lattice. This statement gives the\n"
		"    name of the current lattice for editing, and creates a new lattice if\n"
		"    needed."},
	{"statement","Statements about lattices",1,"type",
		"  * type type",
		"    Type of the lattice. At present, this accepts two type strings, \"nsv\" and\n"
		"    \"pde\", which stand for next-subvolume method and partial differential\n"
		"    equation method, respectively. However, only the NSV method has been\n"
		"    implemented, so that's the only type that should be entered. This statement\n"
		"    is optional, with NSV assumed if it is not entered."},
	{"statement","Statements about lattices",1,"port",
		"  * port port",
		"    Name of the port that the lattice uses to exchange molecules with the\n"
		"    particle-based simulation."},
	{"statement","Statements about lattices",1,"boundaries",
		"  * boundaries dim pos_1 pos_2\n"
		"  * boundaries dim pos_1 pos_2 type",
		"    Creates lower and upper boundaries for the lattice region, where dim is the\n"
		"    dimension that is bounded in this statement, pos_1 is the lower bound, and\n"
		"    pos_2 is the upper bound. In the second form, type is a character that\n"
		"    represents the boundary type, which may be \"r\" for reflective or \"p\" for\n"
		"    periodic. This syntax is essentially identical to the boundaries statement\n"
		"    that is used to define the particle-based simulation volume."},
	{"statement","Statements about lattices",1,"lengthscale",
		"  * lengthscale x_1\n"
		"  * lengthscale x_1 x_2\n"
		"  * lengthscale x_1 x_2 x_3",
		"    Specifies the partition spacing within the lattice region of space. Use the\n"
		"    first form for 1D systems, the second for 2D systems, and the third for 3D\n"
		"    systems. The partition spacing values should be even divisors of the\n"
		"    lattice dimensions that are given with the boundaries statement."},
	{"statement","Statements about lattices",1,"species",
		"  * species species_1 species_2 ...",
		"    List of species that should be used in the lattice region of space. These\n"
		"    species need to have been declared previously in the particle region of\n"
		"    space. This line may be entered multiple times. Rather than listing all\n"
		"    species, the \"all\" keyword can be used to state that all of the current\n"
		"    particle-side species should also be used on the lattice side."},
	{"statement","Statements about lattices",1,"make_particle",
		"  * make_particle face species_1 species_2 ...",
		"    Causes all molecules of the listed species to be converted from lattice\n"
		"    representation to particle representation if they diffuse across the face\n"
		"    called face (front, back, or both) of the lattice's port."},
	{"statement","Statements about lattices",1,"reaction",
		"  * reaction reaction_1 reaction_2 ...\n"
		"  * reaction move reaction_1 reaction_2 ...",
		"    List of reactions that should be used in the lattice region of space. These\n"
		"    reactions need to have been fully defined previously in the particle region\n"
		"    of space. Rather than listing all reactions, the keyword \"all\" can be used\n"
		"    to state that all of the current particle-side reactions should also be\n"
		"    functional on the lattice side. If the keyword \"move\" is given in the list,\n"
		"    as in the latter form above, then all subsequent listed reactions are\n"
		"    \"moved\" to the lattice side, meaning that they are functional on the\n"
		"    lattice side but become non-functional on the particle side. In this case,\n"
		"    they are still defined on the particle side, but are simply disabled."},
	{"statement","Statements about lattices",1,"mol",
		"  * mol nmol name pos_0 pos_1 ... pos_(dim-1)",
		"    This adds molecules to the starting state of the simulation in the lattice\n"
		"    region of space. This statement is essentially identical to the statement\n"
		"    with the same name that is in the particle portion of the configuration\n"
		"    file. The lattice regions starts with nmol type name molecules at location\n"
		"    pos. Each of the dim elements of the position may be a number to give the\n"
		"    actual position of the molecule or molecules; or the letter \"u\" to indicate\n"
		"    that the position for each molecule should be a random value between the\n"
		"    bounding walls, chosen from a uniform density; or a position range which is\n"
		"    given as two numbers separated with a hyphen."},
	{"statement","Statements about lattices",1,"end_lattice",
		"  * end_lattice",
		"    End of a block of lattice definitions. Lattice statements are no longer\n"
		"    recognized but other simulation statements are."},
	{"statement","Statements for simulation settings",0,"random_seed",
		"  random_seed seed",
		"    Seed for random number generator, which can be any integer. If this line is\n"
		"    not entered (or if you set the seed value to \"time\"), the current time is\n"
		"    used as a seed, producing different sequences for each run. (This statement\n"
		"    was called rand_seed through version 2.28.)"},
	{"statement","Statements for simulation settings",0,"accuracy",
		"  accuracy float",
		"    A parameter that determines the quantitative accuracy of the simulation, on\n"
		"    a scale from 0 to 10. Low values are less accurate but run faster. Default\n"
		"    value is 10, for maximum accuracy. Bimolecular reactions are only checked\n"
		"    for pairs of reactants that are both within the same virtual box when\n"
		"    accuracy is 0 to 2.99, reactants in nearest neighboring boxes are\n"
		"    considered as well when accuracy is 3 to 6.99, and reactants in all types\n"
		"    of neighboring boxes are checked when accuracy is 7 to 10."},
	{"statement","Statements for simulation settings",0,"molperbox",
		"  molperbox float",
		"    Virtual boxes are set up initially so the average number of molecules per\n"
		"    box is no more than this value. The default value is 5. boxsize is an\n"
		"    alternate way of entering comparable information."},
	{"statement","Statements for simulation settings",0,"boxsize",
		"  boxsize float",
		"    Rather than using molperbox to specify the sizes of the virtual boxes,\n"
		"    boxsize can be used to request the width of the boxes. The actual box\n"
		"    volumes will be no larger than the volume calculated from the width given\n"
		"    here."},
	{"statement","Statements for simulation settings",0,"gauss_table_size",
		"  gauss_table_size int",
		"    This sets the size of a lookup table that is used to generate\n"
		"    Gaussian-distributed random numbers. It needs to be an integer power of 2.\n"
		"    The default value is 4096, which should be appropriate for nearly all\n"
		"    applications."},
	{"statement","Statements for simulation settings",0,"epsilon",
		"  epsilon float",
		"    Maximum allowed distance separation between a surface-bound molecule and\n"
		"    the surface. The default value, which is extremely small, is good for most\n"
		"    applications."},
	{"statement","Statements for simulation settings",0,"margin",
		"  margin float",
		"    The distance inside of a panel edge to which Smoldyn moves surface-bound\n"
		"    molecules that diffuse off of a panel. The default value, which is\n"
		"    extremely small, is good for most applications."},
	{"statement","Statements for simulation settings",0,"neighbor_dist",
		"  neighbor_dist float",
		"    Maximum distance that surface-bound molecules will jump across space to\n"
		"    diffuse from one panel to a neighboring panel. In Smoldyn 2.37 and higher\n"
		"    versions, the default for this value is extremely small, just large enough\n"
		"    to prevent round-off error. It should not need to be changed. In prior\n"
		"    versions, the default value was 3 times the maximum rms step length of\n"
		"    surface-bound molecules, which was necessary due to a different\n"
		"    surface-bound molecule diffusion algorithm."},
	{"command","Simulation control commands",0,"stop",
		"  stop",
		"    Stop the simulation."},
	{"command","Simulation control commands",0,"pause",
		"  pause",
		"    This puts the simulation in pause mode. If opengl graphics are used,\n"
		"    continuation occurs when the user presses the spacebar. When graphics are\n"
		"    not used, the user is told to press enter."},
	{"command","Simulation control commands",0,"beep",
		"  beep",
		"    The computer beeps when this is reached. Nothing else is done."},
	{"command","Simulation control commands",0,"keypress",
		"  keypress char",
		"    Send a signal to the graphics manipulation component of the program to\n"
		"    execute the behavior that would occur when a key is pressed. For the\n"
		"    arrows, and shift-arrows, the character should be \"r\" for right, \"l\" for\n"
		"    left, \"u\" for up, \"d\" for down, and the respective upper case characters\n"
		"    for the shift-arrows."},
	{"command","Simulation control commands",0,"setflag",
		"  setflag number",
		"    Sets the global command flag value to number, which can be a floating point\n"
		"    value. This is generally used after a conditional command, and is then\n"
		"    queried by one or more ifflag commands."},
	{"command","Simulation control commands",0,"setrandseed",
		"  setrandseed seed",
		"    Sets the random number seed to the specified integer value. If the seed\n"
		"    listed is less than 0, the current time is used for the seed."},
	{"command","Simulation control commands",0,"setgraphics",
		"  setgraphics type",
		"    Sets the display graphics to type type. If graphics were not set up\n"
		"    initially, using the graphics statement, this command does nothing.\n"
		"    Otherwise, options for type are \"opengl\" or \"opengl_good\"."},
	{"command","Simulation control commands",0,"setgraphic_iter",
		"  setgraphic_iter timesteps",
		"    Sets the graphics update interval to timesteps time steps. This is only\n"
		"    functional if graphics were set up initially, using the graphics statement."},
	{"command","Simulation control commands",0,"updategraphics",
		"  updategraphics",
		"    Update the graphics window."},
	{"command","File manipulation commands",0,"overwrite",
		"  overwrite filename",
		"    Erases the output file called filename but leaves it open for more writing."},
	{"command","File manipulation commands",0,"incrementfile",
		"  incrementfile filename",
		"    A new output file is created based upon the filename. The first time this\n"
		"    is called the filename is appended with a \"_001\", which is then incremented\n"
		"    with subsequent calls to \"_002\", and so on. These numbers precede any\n"
		"    suffix on the filename."},
	{"command","Conditional commands",0,"if",
		"  if value_1 symbol value_2 command",
		"    Runs command command, depending on the relative values of value_1 and\n"
		"    value_2. The symbol character can be \"<\", \">\" or \"=\"."},
	{"command","Conditional commands",0,"ifflag",
		"  ifflag symbol number command",
		"    Run command command, depending on the value of the global command flag.\n"
		"    Enter symbol as \"<\" if command should be run if the flag value is less than\n"
		"    number, as \">\" for the flag value greater than number, and as \"=\" for the\n"
		"    flag value equal to number."},
	{"command","Conditional commands",0,"ifprob",
		"  ifprob value command",
		"    Run command command with probability value, which should be between 0 and\n"
		"    1. If you want to run multiple commands with this probability use the\n"
		"    setflag and ifflag commands."},
	{"command","Conditional commands",0,"ifno",
		"  ifno species(state) command",
		"    Run command command if no molecule of type species remains. The molecule\n"
		"    state state is optional, with \"solution\" as a default. The name and/or the\n"
		"    state may be \"all\"."},
	{"command","Conditional commands",0,"ifless",
		"  ifless species(state) num command",
		"    Run command command if there are fewer than num molecules of type species\n"
		"    remaining. The molecule state state is optional, with \"solution\" as a\n"
		"    default. The name and/or the state may be \"all\"."},
	{"command","Conditional commands",0,"ifmore",
		"  ifmore species(state) num command",
		"    Run command command if there are more than num molecules of type species.\n"
		"    The molecule state state is optional, with \"solution\" as a default. The\n"
		"    name and/or the state may be \"all\"."},
	{"command","Conditional commands",0,"ifincmpt",
		"  ifincmpt species(state) char number compartment command",
		"    Run command command depending on how the number of molecules of type\n"
		"    species within compartment compartment compares with number. Enter char as\n"
		"    \"<\" if command should be run with less than number molecules, as \">\" for\n"
		"    more than number, or as \"=\" for equal to number. A space is required\n"
		"    between this symbol and number. The molecules' state state is optional,\n"
		"    with \"solution\" as a default. The species and/or state may be \"all\"."},
	{"command","Conditional commands",0,"ifchange",
		"  ifchange species(state) char num command",
		"    Run command command if the number of molecules of type species changes (or\n"
		"    doesn't change) relative to the previous time this command was called. The\n"
		"    molecule state state is optional, with \"solution\" as a default. The name\n"
		"    and/or the state may be \"all\". Enter char as \">\" to respond to a difference\n"
		"    that is greater than num, \"<\" to respond to a difference that is less than\n"
		"    num, \"=\" to respond to a difference that is exactly equal to num, or \"!\" to\n"
		"    respond to a difference that does not equal num. For example, enter char\n"
		"    and num as \"! 0\" to respond to any change in molecule numbers, or as \"<\n"
		"    -10\" to respond to any decrease that exceeds 10 molecules."},
	{"command","System observation commands",0,"warnescapee",
		"  warnescapee species(state) filename",
		"    Looks for molecules of type species that are outside the system boundaries,\n"
		"    printing results to filename. If there are none, nothing is printed. For\n"
		"    each molecule that escaped during the last time step, this prints a line of\n"
		"    text that says where the molecule was, where it is, and where it crossed\n"
		"    the last surface. Setting species to \"all\" allows all molecule types to be\n"
		"    checked. This needs to be run at every time step to catch all escaping\n"
		"    molecules."},
	{"command","System observation commands",0,"warnescapeecmpt",
		"  warnescapeecmpt species(state) compartment filename",
		"    This is the same as warnescapee, but looks for molecules escaping from\n"
		"    compartment."},
	{"command","System observation commands",0,"echo",
		"  echo filename \"string\"",
		"    Just prints the text within double quotes to the file, without any terminal\n"
		"    newline. If you want a newline, include \"\\n\" at the end of the string. The\n"
		"    quotes need to be plain quotes, not curly quotes."},
	{"command","System observation commands",0,"evaluate",
		"  evaluate filename expression",
		"    Evaluates the given mathematical expression, printing the result to the\n"
		"    file. The results are only likely to be interesting if the expression is\n"
		"    one of the Smoldyn functions."},
	{"command","System observation commands",0,"molcountheader",
		"  molcountheader filename",
		"    This prints one line of display with the word \"time\" and then the name of\n"
		"    each molecule species. This is intended to be used as a header line for the\n"
		"    molcount, molcountinbox, etc. commands."},
	{"command","System observation commands",0,"molcount",
		"  molcount filename",
		"    Each time this command is executed, one line of display is printed to the\n"
		"    listed file, giving the time and the number of molecules for each molecular\n"
		"    species. Molecule states are ignored. The ordering used is the same as was\n"
		"    given in the species command. This command accounts for molecules in\n"
		"    lattices and their associated ports."},
	{"command","System observation commands",0,"molcountinbox",
		"  molcountinbox low_x high_x filename\n"
		"  molcountinbox low_x high_x low_y high_y filename\n"
		"  molcountinbox low_x high_x low_y high_y low_z high_z filename",
		"    Each time this command is executed, one line of display is printed to the\n"
		"    listed file, giving the time and the number of molecules that are within\n"
		"    the box that is defined by the low and high parameter, for each molecular\n"
		"    species. Molecule states are ignored. The ordering used is the same as was\n"
		"    given in the species statement."},
	{"command","System observation commands",0,"molcountincmpt",
		"  molcountincmpt compartment filename",
		"    Each time this command is executed, one line of display is printed to the\n"
		"    listed file, giving the time and the number of molecules that are within\n"
		"    the compartment compartment for each molecular species. Only solution-phase\n"
		"    molecules are listed. The ordering used is the same as was given in the\n"
		"    species statement."},
	{"command","System observation commands",0,"molcountincmpts",
		"  molcountincmpts compartment_1 compartment_1 ... compartment_n filename",
		"    Each time this command is executed, one line of display is printed to the\n"
		"    listed file, giving the time and the number of molecules that are within\n"
		"    each of the compartments listed, for each molecular species. Up to 16\n"
		"    compartments may be listed. Only solution-phase molecules are reported to\n"
		"    the output. The molecule ordering used is the same as was given in the\n"
		"    species statement."},
	{"command","System observation commands",0,"molcountincmpt2",
		"  molcountincmpt2 compartment state filename",
		"    Identical to molcountincmpt except that this counts molecules that are in\n"
		"    state state. Entering state as \"all\" means that molecules of all states are\n"
		"    counted. Note that the surfaces that bound a compartment are included in\n"
		"    that compartment."},
	{"command","System observation commands",0,"molcountonsurf",
		"  molcountonsurf surface filename",
		"    Each time this command is executed, one line of display is printed to the\n"
		"    listed file, giving the time and the number of molecules that are bound to\n"
		"    the surface surface for each molecular species. The molecule state is not\n"
		"    printed. The ordering used is the same as was given in the species\n"
		"    statement."},
	{"command","System observation commands",0,"molcountspace",
		"  molcountspace species(state) axis low high bins average filename\n"
		"  molcountspace species(state) axis low high bins low high average filename\n"
		"  molcountspace species(state) axis low high bins low high low high average filename",
		"    This command measures a line profile of molecules. It only counts molecules\n"
		"    of type species, with an optional state specification, although species\n"
		"    and/or state can be \"all\". The line profile is along axis number axis,\n"
		"    which is \"x\", \"y\", or \"z\" (or a number between 0 and the system\n"
		"    dimensionality minus 1), extends from low to high, and is composed of bins\n"
		"    equally spaced bins (i.e. it's a histogram). These bins extend exactly from\n"
		"    low to high, and thus do not count any molecules that are outside this\n"
		"    range. For two dimensions, the line width and lateral position are\n"
		"    specified with another pair of low and high values; for three dimensions,\n"
		"    two more pairs of low and high values are required, which now specify the\n"
		"    sides of a rectangular cross-section tube.\n"
		"\n"
		"    To illustrate the sequence of parameters, suppose the command is used in a\n"
		"    3-D system to show concentration variation along the y-axis. In this case,\n"
		"    axis is \"y\", the first low and high indicate the ends of the measurement\n"
		"    range along the y-axis, the next low and high indicate the domain on the\n"
		"    x-direction, and the third low and high indicate the domain on the\n"
		"    z-direction. Set the average input to 0 to not use averaging, in which case\n"
		"    there is output at every command execution. Otherwise, this only produces\n"
		"    an output every average iterations, at which point it outputs means that\n"
		"    were collected over the preceding iterations. At each output time, the\n"
		"    command outputs a single line of text to filename with the time followed by\n"
		"    the numbers (or average numbers) of the specified molecules in each\n"
		"    histogram bin. This command accounts for molecules in lattices, but not for\n"
		"    molecules in ports."},
	{"command","System observation commands",0,"molcountspace2d",
		"  molcountspace2d species(state) z low_x high_x bins_x low_y high_y bins_y average filename\n"
		"  molcountspace2d species(state) axis low high bins low high bins low high average filename",
		"    This command measures a 2D histogram of molecules. It is identical to\n"
		"    molcountspace, but for 2D. The area is perpendicular to the listed axis\n"
		"    (must be entered as \"z\" for 2D simulations and selectable for 3D\n"
		"    simulations). It extends from low to high, and is composed of bins equally\n"
		"    spaced bins, entered separately for each of the two axes. For 3D\n"
		"    simulations, region thickness is specified with another pair of low and\n"
		"    high values. Set the average input to 0 to not use averaging, in which case\n"
		"    there is output at every command execution. Otherwise, this only produces\n"
		"    an output every average iterations, at which point it outputs means that\n"
		"    were collected over the preceding iterations. At each output time, the\n"
		"    command outputs the time to filename, followed by a grid of numbers of the\n"
		"    molecules in each histogram bin. This command does not account for\n"
		"    molecules in lattices or ports."},
	{"command","System observation commands",0,"molcountspaceradial",
		"  molcountspaceradial species(state) center_x radius bins average filename\n"
		"  molcountspaceradial species(state) center_x center_y radius bins average filename\n"
		"  molcountspaceradial species(state) center_x center_y center_z radius bins average filename",
		"    This command measures a radial profile of molecules. It is identical to\n"
		"    molcountspace, except that counts molecules in radial rings, rather than\n"
		"    along a line profile. It only counts molecules of type species, with an\n"
		"    optional state specification, although species and/or state can be \"all\".\n"
		"    Enter the center position in center, with the number of entries equal to\n"
		"    the system dimensionality, and the investigated radius in radius. The\n"
		"    histogram is comprised of bins equally spaced bins. The volume investigated\n"
		"    includes all edges. Set the average input to 0 to not use averaging, in\n"
		"    which case there is output at every command execution. Otherwise, this only\n"
		"    produces an output every average iterations, at which point it outputs\n"
		"    means that were collected over the preceding iterations. At each output\n"
		"    time, the command outputs a single line of text to filename with the time\n"
		"    followed by the numbers (or average numbers) of the specified molecules in\n"
		"    each histogram bin. This command does not account for molecules in lattices\n"
		"    or ports."},
	{"command","System observation commands",0,"molcountspacepolarangle",
		"  molcountspacepolarangle species(state) center_x center_y pole_x pole_y radius_min radius_max bins average filename\n"
		"  molcountspacepolarangle species(state) center_x center_y center_z pole_x pole_y pole_z radius_min radius_max bins average filename",
		"    This command measures a polar angle profile of molecules. It is identical\n"
		"    to molcountspace (and molcountspaceradial), except that counts molecules in\n"
		"    angular segments, rather than along a line profile. It only counts\n"
		"    molecules of type species, with an optional state specification, although\n"
		"    species and/or state can be \"all\". Enter the center position in center,\n"
		"    with the number of entries equal to the system dimensionality. Enter the\n"
		"    vector that points towards the pole in pole, again with the number of\n"
		"    entries equal to the system dimensionality. All molecules between\n"
		"    radius_min and radius_max will be included; set either or both to -1 to\n"
		"    remove the respective constraint. The histogram is composed of bins equally\n"
		"    spaced bins. These bins extend from 0 to 2pi for a 2D system and from 0 to\n"
		"    pi in a 3D system. The volume investigated includes all edges. Set the\n"
		"    average input to 0 to not use averaging, in which case there is output at\n"
		"    every command execution. Otherwise, this only produces an output every\n"
		"    average iterations, at which point it outputs means that were collected\n"
		"    over the preceding iterations. At each output time, the command outputs a\n"
		"    single line of text to filename with the time followed by the numbers (or\n"
		"    average numbers) of the specified molecules in each histogram bin. This\n"
		"    command does not account for molecules in lattices or ports."},
	{"command","System observation commands",0,"radialdistribution",
		"  radialdistribution species_1(state) species_2(state) radius bins average filename",
		"    Computes the radial distribution function for molecules of species_2 about\n"
		"    those of species_1. These are allowed to be the same species, can include\n"
		"    wildcards, can be \"all\", etc. Enter the maximum radius to be considered in\n"
		"    radius, the number of bins in the histogram in bins, the number of\n"
		"    iterations to be averaged together in average (or 0 for no averaging), and\n"
		"    the output filename in filename. Outputs the time followed by the radial\n"
		"    distribution function, where the radial distribution function values are\n"
		"    the average molecule densities (units of inverse volume) in each radial\n"
		"    bin. Divide these results by the overall average molecule density to get\n"
		"    the conventional radial distribution function, which typically approaches 1\n"
		"    for large distances. This function accounts for periodic boundaries if they\n"
		"    are used."},
	{"command","System observation commands",0,"radialdistribution2",
		"  radialdistribution2 species_1(state) species2(state) low_x high_x low_y high_y low_z high_z radius bins average filename",
		"    Identical to radialdistribution except that this also allows selection of a\n"
		"    volume region. Enter the low and high values for as many dimensions as the\n"
		"    simulation uses. This computes the radial distribution about all molecules\n"
		"    of species_1 that are within the given volume; species_2 molecules are\n"
		"    considered that are outside of this volume (up to distance radius outside\n"
		"    of it)."},
	{"command","System observation commands",0,"molcountspecies",
		"  molcountspecies species(state) filename",
		"    Prints out a single line of text to filename with time and the number of\n"
		"    molecules of the listed species that are in state state. Either or both of\n"
		"    species and state may be \"all\". If state is not included, solution is\n"
		"    assumed."},
	{"command","System observation commands",0,"molcountspecieslist",
		"  molcountspecieslist filename species(state) species(state) ... species(state)",
		"    Prints out a single line of text to filename with time and the number of\n"
		"    molecules of each of the listed species and states. Either or both of\n"
		"    species and state may be \"all\". If state is not included, solution is\n"
		"    assumed."},
	{"command","System observation commands",0,"mollistsize",
		"  mollistsize listname filename",
		"    Prints out a single line of text to filename with the total number of\n"
		"    molecules in the molecule list named listname. This is allowed to be \"all\"."},
	{"command","System observation commands",0,"listmols",
		"  listmols filename",
		"    This prints out the identity, state, location, and serial number of every\n"
		"    molecule in the system to the listed file name, using a separate line of\n"
		"    text for each molecule."},
	{"command","System observation commands",0,"listmols2",
		"  listmols2 filename",
		"    This is very similar to listmols but has a slightly different output\n"
		"    format. Each line of text is preceded by the \"time counter\", which is an\n"
		"    integer that starts at 1 and is incremented each time the routine is\n"
		"    called. Also, the species and state names of molecules are not printed, but\n"
		"    instead the species and state numbers are printed."},
	{"command","System observation commands",0,"listmols3",
		"  listmols3 species(state) filename",
		"    This is identical to listmols2 except that it only prints information about\n"
		"    molecules of type species. state is optional; species and/or state can be\n"
		"    \"all\"."},
	{"command","System observation commands",0,"listmols4",
		"  listmols4 species(state) filename",
		"    This is identical to listmols3 except that it accounts for wrap-arounds\n"
		"    when displaying molecule positions. In other words, if the x-axis ranges\n"
		"    from 0 to 10, a molecule starts in the middle at x = 5 and diffuses to the\n"
		"    right for a full lap, returning to the middle of the system, then its x\n"
		"    value is printed here as 15, rather than as 5 as it is for listmols3. state\n"
		"    is optional; species and/or state can be \"all\"."},
	{"command","System observation commands",0,"listmolscmpt",
		"  listmolscmpt species(state) cmpt filename",
		"    This prints out the time counter (see listmols2), species, state, and\n"
		"    location, and serial number of every molecule that is within compartment\n"
		"    cmpt. It only prints information about molecules of type species. state is\n"
		"    optional; species and/or state can be \"all\"."},
	{"command","System observation commands",0,"listmolssurf",
		"  listmolssurf species(state) surface filename",
		"    This prints out the time counter (see listmols2), and then the species\n"
		"    number, state number, location, surface name bound to, colon, panel name\n"
		"    bound to, and serial number of every molecule that is bound to surface\n"
		"    surface, with one line per molecule. It only prints information about\n"
		"    molecules of type species. state is optional. species and/or state and/or\n"
		"    surface can be \"all\"."},
	{"command","System observation commands",0,"molpos",
		"  molpos species(state) filename",
		"    This prints out the time and then the positions of all molecules of type\n"
		"    species on a single line of text, to the listed filename. state is\n"
		"    optional; species and/or state can be \"all\"."},
	{"command","System observation commands",0,"trackmol",
		"  trackmol serno filename",
		"    Outputs the time and the species, state, serial number, location, and\n"
		"    inside vs. outside compartment status for each compartment of the single\n"
		"    molecule with serial number serno. This stops after it finds the first\n"
		"    molecule with the requested serial number. This supports two-part serial\n"
		"    numbers (see reaction_serialnum) in which a match occurs if serno exactly\n"
		"    matches either the whole molecule serial number or either half of it."},
	{"command","System observation commands",0,"molmoments",
		"  molmoments species(state) filename",
		"    This prints out the time and then the positional moments of the molecule\n"
		"    type given to the listed file name. All the moments are printed on a single\n"
		"    line of text; they are the number of molecules, the mean position vector\n"
		"    (dim values), and the variances on each axis and combination of axes (dim^2\n"
		"    values). state is optional; neither species nor state can be \"all\"."},
	{"command","System observation commands",0,"savesim",
		"  savesim filename",
		"    This writes the complete state of the current system to the listed file\n"
		"    name, in a format that can be loaded in later as a configuration file. Note\n"
		"    that minor file editing is often desirable before simulating a file saved\n"
		"    in this manner. In particular, the saved file will declare its own name as\n"
		"    an output file name, which will erase the configuration file."},
	{"command","System observation commands",0,"meansqrdisp",
		"  meansqrdisp species(state) dim filename",
		"    This function is used to measure mean square displacements (diffusion\n"
		"    rates) of molecules of type species, along dimension dim (\"x\", \"y\", or \"z\",\n"
		"    or 0, 1, or 2) printing the results to filename. When it is first invoked,\n"
		"    it records the positions of all molecules of type species. Then, and every\n"
		"    subsequent time it is called, it compares the current positions of all\n"
		"    molecules that still exist to the old ones, calculates the average squared\n"
		"    displacement (<r^2>), and prints the time and that number to a single line\n"
		"    in the output file. If dim is \"all\", this sums the mean square displacement\n"
		"    for all dimensions, otherwise dim should be a dimension number. This\n"
		"    accounts for periodic boundaries. state is optional; neither species nor\n"
		"    state can be \"all\". This prints out three numbers in each line: time,\n"
		"    <r^2>, and <r^4>. This command does not work if multiple molecules have the\n"
		"    same serial number (which can only happen if you use the reaction_serialnum\n"
		"    statement). For molecules with two-part serial numbers, it determines\n"
		"    molecule identity based on only the right part.\n"
		"\n"
		"    To interpret these results, diffusion typically leads to a Gaussian\n"
		"    concentration profile. In this case, <r^2> = 2Dt and <r^4> = 12D^2t^2 in 1\n"
		"    dimension; <r^2> = 4Dt and <r^4> = 32D^2t^2 in 2 dimensions; and <r^2> =\n"
		"    6Dt and <r^4> = 60D^2t^2 in 3 dimensions, where D is the effective\n"
		"    diffusion coefficient and t is the time. Most researchers only use the\n"
		"    <r^2> value but the <r^4> value is also useful for checking whether the\n"
		"    concentration profile is actually Gaussian or not."},
	{"command","System observation commands",0,"meansqrdisp2",
		"  meansqrdisp2 species(state) dim start report max_mol max_moment filename",
		"    This function is an expanded version of meansqrdisp. As above, it measures\n"
		"    mean square displacements of molecules of type species, along dimension dim\n"
		"    (\"x\", \"y\", or \"z\", or 0, 1, or 2), and prints the results to filename. The\n"
		"    start and report arguments control when this command starts tracking\n"
		"    molecules and when it reports their mean square displacements,\n"
		"    respectively. For start, enter \"i\" to track molecules that exist when the\n"
		"    command is initially invoked, enter \"c\" to track those that are created\n"
		"    after the first call, and enter \"a\" (all) to track both sets of molecules.\n"
		"    For report, enter \"e\" to report on every molecule that is being tracked, or\n"
		"    \"r\" to report on only those that reacted since the command was last called.\n"
		"    In this latter case, the position that is used for a reacted molecule is\n"
		"    its most recently tracked position, since it no longer exists. For example,\n"
		"    if you want to see how far molecules diffuse between their creation in one\n"
		"    reaction and their destruction in another reaction, set start to \"c\" and\n"
		"    report to \"r\". Or, set start to \"i\" and report to \"e\" for this function to\n"
		"    be identical to meansqrdisp. It can track up to max_mol molecules. This\n"
		"    function prints out the time and then results for all moments, even and\n"
		"    odd, from <r^0> (the number of molecules being reported on) to\n"
		"    <r^(max_moment)>. This command accounts for periodic boundaries. state is\n"
		"    optional; neither species nor state can be \"all\". This command does not\n"
		"    work if multiple molecules have the same serial number (which can only\n"
		"    happen if you use the reaction_serialnum statement). For molecules with\n"
		"    two-part serial numbers, it determines molecule identity based on only the\n"
		"    right part."},
	{"command","System observation commands",0,"meansqrdisp3",
		"  meansqrdisp3 species(state) dim start report max_mol change filename command",
		"    This function is quite similar to meansqrdisp and meansqrdisp2. It measures\n"
		"    mean square displacements of molecules of type species, along dimension dim\n"
		"    (\"x\", \"y\", or \"z\", or 0, 1, or 2). Then, this function divides these values\n"
		"    by the molecules' ages to compute effective diffusion coefficients and\n"
		"    prints the results to filename. The effective diffusion coefficient average\n"
		"    is weighted using the molecule ages, so that old molecules have\n"
		"    proportionately greater weight in the average than young molecules. The\n"
		"    start and report arguments control when this command starts tracking\n"
		"    molecules and when it reports their mean square displacements,\n"
		"    respectively. For start, enter \"i\" to track molecules that exist when the\n"
		"    command is initially invoked, enter \"c\" to track those that are created\n"
		"    after the first call, and enter \"a\" (all) to track both sets of molecules.\n"
		"    For report, enter \"e\" to report on every molecule that is being tracked, or\n"
		"    \"r\" to report on only those that reacted since the command was last called.\n"
		"    In this latter case, the position that is used for a reacted molecule is\n"
		"    its most recently tracked position, since it no longer exists. It can track\n"
		"    up to max_mol molecules. This function prints out the time, the number of\n"
		"    molecules reported on, and the effective diffusion coefficient. Note that\n"
		"    the first command run will always output an effective diffusion coefficient\n"
		"    of \"NaN\" (or #1.IND on Windows systems) due to a 0/0 division error arising\n"
		"    from 0 displacement divided by 0 time difference. If the effective\n"
		"    diffusion coefficient changed less than change since the last time this\n"
		"    function was executed, then the command command is run (e.g. if change is\n"
		"    0.01 then a fractional diffusion coefficient change of 1% or less will\n"
		"    cause command to be run). See the example file called meansqrdisp3.txt.\n"
		"    This command accounts for periodic boundaries. The species cannot be \"all\".\n"
		"    The state is optional. If the state is \"all\", then molecules for all states\n"
		"    of this species must be stored in the same molecule list. No warning is\n"
		"    issued if this is not the case, but some molecules simply won't be counted.\n"
		"    This command does not work if multiple molecules have the same serial\n"
		"    number (which can only happen if you use the reaction_serialnum statement).\n"
		"    For molecules with two-part serial numbers, it determines molecule identity\n"
		"    based on only the right part."},
	{"command","System observation commands",0,"residencetime",
		"  residencetime species(state) start report summary_out list_out max_mol filename",
		"    This function computes residence times of individual molecules of type\n"
		"    species, thus showing how long they have existed in the system. As with\n"
		"    meansqrdisp2 and meansqrdisp3, the start and report arguments control when\n"
		"    this command starts tracking molecules and when it reports their residence\n"
		"    times, respectively. For start, enter \"i\" to track molecules that exist\n"
		"    when the command is initially invoked, enter \"c\" to track those that are\n"
		"    created after the first call, and enter \"a\" (all) to track both sets of\n"
		"    molecules. For report, enter \"e\" to report on every molecule that is being\n"
		"    tracked, or \"r\" to report on only those that reacted since the command was\n"
		"    last called. It can track up to max_mol molecules. This function needs to\n"
		"    be invoked at every time step so that molecules can be tracked accurately.\n"
		"    However, output may not be wanted at every time step, so set summary_out to\n"
		"    the number of invocations between when this should print a summary output,\n"
		"    with the time number of molecules, and mean residence time, and set\n"
		"    list_out to the number of invocations between when this should print a list\n"
		"    output, with a list of all molecules with their IDs and their current ages.\n"
		"    In both cases, set values to 0 or less to not have this type of output.\n"
		"    state is optional; neither species nor state can be \"all\". See the\n"
		"    residencetime.txt example file. This command does not work if multiple\n"
		"    molecules have the same serial number (which can only happen if you use the\n"
		"    reaction_serialnum statement)."},
	{"command","System observation commands",0,"diagnostics",
		"  diagnostics type",
		"    Displays diagnostics about various parts of the data structures to the\n"
		"    screen. These are identical to those that are displayed at program\n"
		"    initialization, but for later times. The options for the type word are:\n"
		"    \"simulation\", \"wall\", \"molecule\", \"surface\", \"command\", \"box\", \"reaction\",\n"
		"    \"compartment\", \"port\", \"check\", and \"all\"."},
	{"command","System observation commands",0,"executiontime",
		"  executiontime filename",
		"    Prints a single line of text with the current simulation time and the\n"
		"    number of seconds of real time that the simulation has taken to execute\n"
		"    since the simulation was started."},
	{"command","System observation commands",0,"printLattice",
		"  printLattice filename",
		"    Displays diagnostics about all lattices."},
	{"command","System observation commands",0,"printFilament",
		"  printFilament filament_type:filament code filename",
		"    Prints information about the specified filament. The code input should be a\n"
		"    string of letters; for each one, this prints out that data set. Codes are:\n"
		"    x: segment lengths, endpoint positions, and relative angles, a: relative\n"
		"    quaternions, b: absolute quaternions, f: forces on each node (computed by\n"
		"    this function)."},
	{"command","System observation commands",0,"printFilaments",
		"  printFilaments filename",
		"    Prints out every filament (all types) as a flat polyline of node\n"
		"    coordinates, one line each: FIL <time> <type>:<name> <nseg> <parent-or-\"-\">\n"
		"    x0 y0 [z0] x1 y1 [z1] .... Auto-named daughters are included, so this\n"
		"    captures a whole branched network."},
	{"command","System observation commands",0,"writeVTK",
		"  writeVTK filepath/filename",
		"    Outputs VTK format data for viewing with applications such as Visit or\n"
		"    Paraview. This creates a stack of files in the working directory, or\n"
		"    somewhere else depending on the filepath, for which the names start with\n"
		"    filenameLattice00_00001.vtu and filenameMolecules00001.vtu, where filename\n"
		"    is the entered file name. The filepath directory needs to have been created\n"
		"    beforehand. In contrast to most filenames, this path and name should not be\n"
		"    declared with the \"output_files\" statement. The filename numbers are\n"
		"    incremented for each snapshot. If molecules have two-part serial numbers,\n"
		"    this only considers the right part."},
	{"command","System observation commands",0,"printdata",
		"  printdata data filename [erase]",
		"    Prints data that were recorded by some other command, and stored in data\n"
		"    array data, to the output filename. Set the optional parameter erase to 0\n"
		"    to not have the original data erased after copying (the default) or to 1 to\n"
		"    have the original data erased after copying."},
	{"command","System manipulation commands",0,"set",
		"  set statement",
		"    This command lets you use essentially any statement that can be entered in\n"
		"    a configuration file. The statement can, for example, create new reactions,\n"
		"    add surfaces, change rate constants, etc."},
	{"command","System manipulation commands",0,"pointsource",
		"  pointsource species num pos_x\n"
		"  pointsource species num pos_x pos_y\n"
		"  pointsource species num pos_x pos_y pos_z",
		"    Creates num new molecules of type species and at location pos. Molecule\n"
		"    states are set to solution. This creates exactly num molecules if num is an\n"
		"    integer and a Poisson-distributed random number of molecules with expected\n"
		"    value equal to num if num is a non-integer."},
	{"command","System manipulation commands",0,"volumesource",
		"  volumesource species num pos_(x,low) pos_(x,high)\n"
		"  volumesource species num pos_(x,low) pos_(x,high) pos_(y,low) pos_(y,high)\n"
		"  volumesource species num pos_(x,low) pos_(x,high) pos_(y,low) pos_(y,high) pos_(z,low) pos_(z,high)",
		"    Creates num new molecules of type species and within the location bounded\n"
		"    by pos_low and pos_high. Molecule states are set to solution. This creates\n"
		"    exactly num molecules if num is an integer and a Poisson-distributed random\n"
		"    number of molecules with expected value equal to num if num is a\n"
		"    non-integer."},
	{"command","System manipulation commands",0,"gaussiansource",
		"  gaussiansource species num mean_x sigma_x\n"
		"  gaussiansource species num mean_x sigma_x mean_y sigma_y\n"
		"  gaussiansource species num mean_x sigma_x mean_y sigma_y mean_z sigma_z",
		"    Creates num new molecules of type species with a Gaussian distribution\n"
		"    centered at mean and with standard deviation sigma on each axis. Molecules\n"
		"    are not placed beyond the system boundaries; any attempted placements are\n"
		"    rejected and sampled again. Molecule states are set to solution. This\n"
		"    creates exactly num molecules if num is an integer and a\n"
		"    Poisson-distributed random number of molecules with expected value equal to\n"
		"    num if num is a non-integer."},
	{"command","System manipulation commands",0,"movesurfacemol",
		"  movesurfacemol species(state) prob surface_1:panel_1 surface_2:panel_2 [state2]",
		"    Moves molecules of type species and state state, and which are bound to\n"
		"    panel_1 of surface_1, to panel_2 of surface_2 with probability prob. If\n"
		"    entered, the new molecular state becomes state_2, which may be any state\n"
		"    including fsoln or bsoln; otherwise the molecule state is unchanged. The\n"
		"    new molecule location is at a random location on panel_2 (which contrasts\n"
		"    the behavior of the jump statement). Either or both of panel_1 and panel_2\n"
		"    can be \"all\" for all panels of the respective surface. Also, the species\n"
		"    and/or the state may be \"all\"."},
	{"command","System manipulation commands",0,"killmol",
		"  killmol species(state)",
		"    Kills all molecules of type species. state is optional; species and/or\n"
		"    state may be \"all\"."},
	{"command","System manipulation commands",0,"killmolprob",
		"  killmolprob species(state) prob",
		"    Kills some molecules of type species; the probability of a molecule being\n"
		"    killed is prob (between 0 and 1). state is optional; species and/or state\n"
		"    may be \"all\". prob can be a function of the molecule location using its x,\n"
		"    y, and z values."},
	{"command","System manipulation commands",0,"killmolinsphere",
		"  killmolinsphere species(state) surface",
		"    Kill all molecules of type species that are in any sphere that is a panel\n"
		"    of surface surface. If surface is \"all\" then every surface is scanned.\n"
		"    state is optional; species and/or state may be \"all\"."},
	{"command","System manipulation commands",0,"killmolincmpt",
		"  killmolincmpt species(state) compartment",
		"    Kill all molecules of type species that are in compartment compartment.\n"
		"    state is optional; species and/or state may be \"all\"."},
	{"command","System manipulation commands",0,"killmoloutsidesystem",
		"  killmoloutsidesystem species(state)",
		"    Kill all molecules of type species that are outside of the system\n"
		"    boundaries. state is optional; species and/or state may be \"all\"."},
	{"command","System manipulation commands",0,"fixmolcount",
		"  fixmolcount species num",
		"    Counts the number of solution-phase molecules of type species. If this\n"
		"    count is more than num, then molecules of this type, chosen at random, are\n"
		"    removed until num is reached. Otherwise, molecules are added to random\n"
		"    positions in the system to achieve a total count of num. This function\n"
		"    considers the entire system volume."},
	{"command","System manipulation commands",0,"fixmolcountrange",
		"  fixmolcountrange species low_num high_num",
		"    Exactly like fixmolcount, except that the molecule count is unchanged if it\n"
		"    is between low_num and high_num, and is otherwise modified to bring it to\n"
		"    within the range."},
	{"command","System manipulation commands",0,"fixmolcountonsurf",
		"  fixmolcountonsurf species(state) num surface",
		"    Counts the number of surface-bound molecules of type species and state\n"
		"    state. If this count is more than num, then molecules of this type, chosen\n"
		"    at random, are removed until num is reached. Otherwise, molecules with the\n"
		"    proper state are added to random positions on the surface to achieve a\n"
		"    total count of num."},
	{"command","System manipulation commands",0,"fixmolcountrangeonsurf",
		"  fixmolcountrangeonsurf species(state) low_num high_num surface",
		"    Exactly like fixmolcountonsurf, except that the molecule count is unchanged\n"
		"    if it is between low_num and high_num, and is otherwise modified to bring\n"
		"    it to within the range."},
	{"command","System manipulation commands",0,"fixmolcountincmpt",
		"  fixmolcountincmpt species num compartment",
		"    Counts the number of solution-phase molecules of type species and in\n"
		"    compartment compartment. If this count is more than num, then molecules of\n"
		"    this type, chosen at random, are removed until num is reached. Otherwise,\n"
		"    molecules are added to random positions in the compartment to achieve a\n"
		"    total count of num."},
	{"command","System manipulation commands",0,"fixmolcountrangeincmpt",
		"  fixmolcountrangeincmpt species low_num high_num compartment",
		"    Exactly like fixmolcountincmpt, except that the molecule count is unchanged\n"
		"    if it is between low_num and high_num, and is otherwise modified to bring\n"
		"    it to within the range."},
	{"command","System manipulation commands",0,"equilmol",
		"  equilmol species_1(state_1) species_2(state_2) prob",
		"    Equilibrate these molecules. All molecules of type species_1 and species_2\n"
		"    will be randomly replaced with one of the two types, where type species_2\n"
		"    has probability prob. state_1 and state_2 are optional; defaults are\n"
		"    \"solution\". Neither species nor states may be \"all\". prob can be a function\n"
		"    of the molecule location using its x, y, and z values."},
	{"command","System manipulation commands",0,"replacemol",
		"  replacemol species_1(state_1) species_2(state_2) prob",
		"    Molecules of type species_1 are replaced with ones of type species_2 with\n"
		"    probability prob. States are optional and are solution by default; neither\n"
		"    species nor states may be \"all\". prob can be a function of the molecule\n"
		"    location using its x, y, and z values."},
	{"command","System manipulation commands",0,"replacexyzmol",
		"  replacexyzmol species(state) pos_0 pos_1 ... pos_(dim-1)",
		"    If there is a non-diffusing molecule at exactly position pos, it is\n"
		"    replaced with one of type species. This command stops after one molecule is\n"
		"    found. state is optional and may not be \"all\"; default is solution."},
	{"command","System manipulation commands",0,"replacevolmol",
		"  replacevolmol species_1(state_1) species_2(state_2) frac pos_(0,low) pos_(0,high) pos_(1,low) pos_(1,high) ... pos_(dim-1,high)",
		"    Fraction frac molecules of type species_1 in the volume bounded by pos_low,\n"
		"    pos_high are replaced with ones of type species_2. States are optional and\n"
		"    are solution by default; neither species nor states may be \"all\". frac can\n"
		"    be a function of the molecule location using its x, y, and z values."},
	{"command","System manipulation commands",0,"replacecmptmol",
		"  replacecmptmol species_1(state_1) species_2(state_2) frac compartment",
		"    Fraction frac molecules of type species_1 in the compartment named\n"
		"    compartment are replaced with ones of type species_2. States are optional\n"
		"    and are solution by default; neither species nor states may be \"all\". frac\n"
		"    can be a function of the molecule location using its x, y, and z values."},
	{"command","System manipulation commands",0,"modulatemol",
		"  modulatemol species_1(state_1) species_2(state_2) freq shift",
		"    Modulates molecules of types species_1 and species_2, just like equilmol,\n"
		"    but with a variable probability. Every time this command executes, any of\n"
		"    the two types of molecules in the system are replaced with a molecule of\n"
		"    type species_1 with probability cos(freq*t+shift), where t is the\n"
		"    simulation time, and otherwise with a molecule of type species_2. States\n"
		"    are optional and are solution by default; neither species nor states may be\n"
		"    \"all\"."},
	{"command","System manipulation commands",0,"react1",
		"  react1 species(state) rxn",
		"    All molecules of type species are instantly reacted, resulting in the\n"
		"    products and product placements given by the unimolecular reaction named\n"
		"    rxn. Note that species does not have to be the normal reactant for reaction\n"
		"    rxn. The state is optional; species and/or state may be \"all\"."},
	{"command","System manipulation commands",0,"setrateint",
		"  setrateint rxn rate",
		"    Sets the internal reaction rate of the reaction named rxn to rate. See the\n"
		"    description above for rate_internal for the meanings of rate for the\n"
		"    different reaction orders. Units are not allowed for this function."},
	{"command","System manipulation commands",0,"shufflemollist",
		"  shufflemollist listname",
		"    Randomly shuffles the sequence of molecules in the molecule list called\n"
		"    listname. Enter \"all\" for all lists. This is useful for systems that are\n"
		"    especially ordered or for simulations with unusually long time steps,\n"
		"    because these situations may make simulation results depend on the molecule\n"
		"    list sequences."},
	{"command","System manipulation commands",0,"shufflereactions",
		"  shufflereactions reactant_1 reactant_2",
		"    Randomly shuffles the sequence of bimolecular reactions that reactant\n"
		"    species reactant_1 and reactant_2 can undergo (all states are indexed\n"
		"    together). Either or both or reactant_1 and reactant_2 can be \"all\"."},
	{"command","System manipulation commands",0,"settimestep",
		"  settimestep dt",
		"    Changes the simulation time step to dt. This changes the diffusion step\n"
		"    lengths, reaction binding and unbinding radii, and surface action\n"
		"    probabilities. Caution should be used if the time step is increased to\n"
		"    longer than the original value because no checks are made to ensure that\n"
		"    the simulation will still yield accurate results."},
	{"command","System manipulation commands",0,"porttransport",
		"  porttransport port_1 port_2",
		"    Transports molecules from the output buffer of port_1 to the input of\n"
		"    port_2. These may be the same ports."},
	{"command","System manipulation commands",0,"excludebox",
		"  excludebox low_x high_x\n"
		"  excludebox low_x high_x low_y high_y\n"
		"  excludebox low_x high_x low_y high_y low_z high_z",
		"    This keeps all molecules from entering a rectanguloid box within the system\n"
		"    volume. Use the first form for one dimension, the second for two\n"
		"    dimensions, and the third for three dimensions. Molecules that start within\n"
		"    the box can stay there, but any molecule that tries to diffuse into the box\n"
		"    is returned to its location at the previous time step. This command needs\n"
		"    to be run at every time step to work properly."},
	{"command","System manipulation commands",0,"excludesphere",
		"  excludesphere x rad\n"
		"  excludesphere x y rad\n"
		"  excludesphere x y z rad",
		"    This keeps all molecules from entering a sphere within the system volume.\n"
		"    Use the first form for one dimension, the second for two dimensions, and\n"
		"    the third for three dimensions; the coordinates given are the sphere center\n"
		"    and rad is the sphere radius. Molecules that start within the sphere can\n"
		"    stay there, but any molecule that tries to diffuse into the sphere is\n"
		"    returned to its location at the previous time step. This command needs to\n"
		"    be run at every time step to work properly."},
	{"command","System manipulation commands",0,"includeecoli",
		"  includeecoli",
		"    An E. coli shape is defined as a cylinder with hemispherical endcaps, where\n"
		"    the long axis of the bacterium extends the length of the x-axis within the\n"
		"    system walls and the radius of both the cylinder and the endcaps is half\n"
		"    the spacing between the walls that bound the y-axis. This command moves any\n"
		"    molecule that diffuses out of the E. coli shape back to its location at the\n"
		"    previous time step, or to the nearest surface of the E. coli if it was\n"
		"    outside at the previous time step as well. This command does not need to be\n"
		"    run at every time step to work properly. This only works with a 3\n"
		"    dimensional system."},
	{"command","System manipulation commands",0,"setreactionratemolcount",
		"  setreactionratemolcount rxn c_0 c_1 species_1(state_1) c_2 species_2(state_2) ...",
		"    This sets the rate of the reaction named rxn to: c_0, plus c_1 times the\n"
		"    number of molecules of species_1 and state_1, plus c_2 times the number of\n"
		"    molecules of species_2 and state_2, plus any additional coefficients and\n"
		"    species that are listed here. Species and/or states may be \"all\" and\n"
		"    wildcards are permitted. If the reaction rate is computed to be a negative\n"
		"    value, it is set to zero instead (and no warning is issued). Units are not\n"
		"    allowed in this function."},
	{"command","System manipulation commands",0,"expandsystem",
		"  expandsystem expand_x expand_y expand_z",
		"    Expand, or contract, everything in system, which includes molecule\n"
		"    locations and surfaces, about the center of the system. Expands by expand_x\n"
		"    along the x-coordinate, by expand_y along the y-coordinate, and by expand_z\n"
		"    along the z-coordinate. Enter as many numbers as there are dimensions. Each\n"
		"    number should be 1 for no change, a number larger than 1 for expansion and\n"
		"    a number smaller than 1 for contraction. Negative numbers perform system\n"
		"    inversion. This command can be used, for example, to mimic lengthwise or\n"
		"    diameter growth of a cell. Warning: isotropic expansion or contraction, in\n"
		"    which all three expansion values are equal, generally works well, with no\n"
		"    unintentional transfer of molecules across surfaces. However, anisotropic\n"
		"    expansion or contraction would normally cause some of Smoldyn's panel\n"
		"    shapes to become distorted, including spheres, hemispheres, cylinders, and\n"
		"    disks. Smoldyn does not support this, so these panels are expanded but not\n"
		"    distorted. In the process, molecules often cross the surfaces\n"
		"    unintentionally and need to be dealt with separately (e.g. killed off). See\n"
		"    the expandsystem.txt example file."},
	{"command","System manipulation commands",0,"translatecmpt",
		"  translatecmpt compartment code delta_x\n"
		"  translatecmpt compartment code delta_x delta_y\n"
		"  translatecmpt compartment code delta_x delta_y delta_z",
		"    Translate the compartment called compartment by the shift value given in\n"
		"    delta_x, delta_y, and delta_z (with fewer values for lower dimensions). The\n"
		"    code value describes which attributes of the compartment should be moved;\n"
		"    add the codes for the individual attributes for the final code value. The\n"
		"    individual codes are: 1 for translating the compartment surfaces, 2 for\n"
		"    translating the molecules that are bound to those surfaces, 4 for\n"
		"    translating the molecules that are within the compartment, and 8 for\n"
		"    shifting the molecules that are outside of the compartment but that get\n"
		"    bumped into by the moving surfaces. Thus, use a code of 15 to get all of\n"
		"    these behaviors at once. With code of 4, all molecules within the\n"
		"    compartment are translated, regardless of their surface actions. With code\n"
		"    of 8, all molecules that a compartment surface would bump into get\n"
		"    translated, unless their surface action is \"transmit\". If a molecule gets\n"
		"    \"squeezed\", meaning that it gets bumped into by the moving compartment, but\n"
		"    then gets bumped back due to some other surface, then that molecule will\n"
		"    end up inside of the compartment."},
	{"command","System manipulation commands",0,"diffusecmpt",
		"  diffusecmpt compartment code stddev_x [cmpt_bound radius nsample]\n"
		"  diffusecmpt compartment code stddev_x stddev_y [cmpt_bound radius nsample]\n"
		"  diffusecmpt compartment code stddev_x stddev_y stddev_z [cmpt_bound radius nsample]",
		"    This is similar to translatecmpt, except that this translates the\n"
		"    compartment by a Gaussian distributed random amount that has standard\n"
		"    deviation on each axis of stddev_x, stddev_y, and stddev_z. Also, this has\n"
		"    three optional parameters: cmpt_bound, radius, and nsample. If they are\n"
		"    entered, then Smoldyn keeps the diffusing compartment within the bounding\n"
		"    compartment called cmpt_bound (assuming it was inside initially). It does\n"
		"    this by computing nsample test points that are on a spherical shell of\n"
		"    radius radius around each of the compartment's interior-defining points and\n"
		"    determines if any of these test points would escape the bounding\n"
		"    compartment during a move. If so, then the move is rejected, and Smoldyn\n"
		"    tries again, up to 10 times. It's important that radius is slightly larger\n"
		"    than the actual distance to the compartment edge and that nsample is\n"
		"    sufficiently large to cover the effective surface adequately because\n"
		"    molecule behavior is unpredictable if a molecule is between two reflective\n"
		"    surfaces that end up crossing each other, even if only briefly and by a\n"
		"    small amount."},
	{"command","System manipulation commands",0,"longrangeforce",
		"  longrangeforce species_1(state) species_2(state) mobility_1 mobility_2 rad_min rad_max equation",
		"    This simulates a long range force between molecules of species_1 and\n"
		"    species_2, moving them in response to it. The force is computed from\n"
		"    equation. This equation needs to be a function of r, which is the radius.\n"
		"    For example, it could be -4*r^(-2)+2*r^(-4), where r represents the\n"
		"    distance between two molecules; do not include any spaces in the equation.\n"
		"    Negative values represent attractive forces, and note that exponents will\n"
		"    probably be negative for most physically reasonable forces. This equation\n"
		"    applies for all separations between rad_min and rad_max, and the force is\n"
		"    zero elsewhere. For computational efficiency, it's a good idea to keep\n"
		"    rad_max reasonably small. Molecules of species_1 move distance mobility_1\n"
		"    delta_t times the force, while those of species_2 move mobility_2 delta_t\n"
		"    times the force, where delta_t is the simulation time step. Except in very\n"
		"    unusual circumstances, both mobilities should be positive values. Note that\n"
		"    this accounts for the simulation time step, which is unusual for commands.\n"
		"    However, it does not account for the command being run at wide intervals,\n"
		"    such as every 2, 3, or 4 time steps. Instead, to be quantitatively\n"
		"    accurate, it needs to run at every time step (or run it every n time steps,\n"
		"    and multiply the force or mobility by n)."},
	{"command","System manipulation commands",0,"translatemol",
		"  translatemol species(state) equation_x\n"
		"  translatemol species(state) equation_x equation_y\n"
		"  translatemol species(state) equation_x equation_y equation_z",
		"    Performs location-dependent drift such as for advection. This translates\n"
		"    molecules of the given species and state (each of which are allowed to be\n"
		"    \"all\") by the displacement that is calculated from the equations, with one\n"
		"    equation for each coordinate. These equations are allowed to be functions\n"
		"    of the position and/or the time; the position is entered as x, y, and/or z,\n"
		"    and the time as time. Do not include spaces in the equations and simply\n"
		"    enter \"0\" for an equation if there's no translation on that axis. For\n"
		"    example, in a 3D system, the three equations y -x 0 cause the molecules to\n"
		"    circle the origin in the x-y plane and stay stationary along the z axis."},
	{"command","System manipulation commands",0,"RotateFilamentToY",
		"  RotateFilamentToY filtype:filname",
		"    This is a specialized command for a particular study and not likely to be\n"
		"    generally useful. It takes a filament and rotates it about the x-axis\n"
		"    (translated to the front of the filament) so that the filament's center of\n"
		"    mass lies along the positive y-axis."},
	};
